(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0038.js"] = [{"id":"poem-f7dc19db892c69f0f7cd3580","title":"玄都观","author":"蜀太后徐氏","dynasty":"唐","verses":["千寻绿嶂夹流溪，登眺因知海岳低。","瀑布迸舂青石碎，轮茵横翦翠峰齐。","步黏苔藓龙桥滑，日闭烟罗鸟径迷。","莫道穹天无路到，此山便是碧云梯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-b07e39b5-eafc-4493-a320-454e7a81149a","tags":[]},{"id":"poem-f7e104c754839f830c6d8602","title":"秋末入匡山船行八首 二","author":"贯休","dynasty":"唐","verses":["芦苇深花里，渔歌一曲长。","人心虽忆越，帆态似浮湘。","石獭衔鱼白，汀茅浸浪黄。","等闲千万里，道在亦无妨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-23391358-ea11-49ab-abf8-a0a209374a39","tags":["庐山"]},{"id":"poem-f7e25738aa999c777d933809","title":"横吹曲辞 前出塞九首 六","author":"杜甫","dynasty":"唐","verses":["挽弓当挽彊，用箭当用长。","射人先射马，擒贼先擒王。","杀人亦有限，列国自有疆。","苟能制侵陵，岂在多杀伤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5683781e-f55a-49ad-8c3a-de7a2f217a35","tags":["哲理","议论","战争"]},{"id":"poem-f7e2d5a95cefd8c222915e8d","title":"唐大飨拜洛乐章 禋和","author":"则天皇后","dynasty":"唐","verses":["百礼崇容，千官肃事。","灵降舞兆，神凝有粹。","奠享咸周，威仪毕备。","奏夏登列，歌雍撤肆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-169ff044-695d-4889-b2d0-3c1bd70dfc6c","tags":[]},{"id":"poem-f7f12aab333ebf6e4201fb59","title":"山鹧鸪词","author":"徐凝","dynasty":"唐","verses":["南越岭头山鹧鸪，传是当时守贞女。","化为飞鸟怨何人，犹有啼声带蛮语。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9ff3b293-afd6-4eef-ad94-aecea2746558","tags":[]},{"id":"poem-f801932c8f7ba6eb58046fd7","title":"相见欢·微云一抹遥峰","author":"纳兰性德","dynasty":"清","verses":["微云一抹遥峰，冷溶溶。","恰与个人清晓，画眉同。","红蜡泪，青绫被，水沉浓。","却与黄茅野店，听西风。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-81","tags":[]},{"id":"poem-f804187a78e0ec09b17f1b82","title":"郊庙歌辞 祀九宫贵神乐章 肃和","author":"不详","dynasty":"唐","verses":["歌工既奏，神位既秩。","天符众星，运行太一。","声和十管，气应中律。","肃肃明廷，介兹元吉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e46ff4fd-f74e-4df3-81dd-5268b6ca2507","tags":[]},{"id":"poem-f81e0a861a472e874369e875","title":"哭吴丞相元中二首  其二","author":"李纲","dynasty":"宋","verses":["宣和之季靖康初，同力同心卫帝居。","扶毂共升新日月，谪官难守旧田庐。","孔光温室不言树，陆贽忠州戒著书。","叹息端荘士君子，岂随草木腐丘墟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-40cd577a-8fd4-4950-813b-e0b2ffa4ce75","tags":[]},{"id":"poem-f8202fc3c41b5b6fafabec9f","title":"闻杜牧赴阙","author":"伍乔","dynasty":"宋","verses":["旧隠匡庐一草堂，今闻携策谒吾皇。","峡云难卷从龙势，古剑终腾出土光。","开翅定期归碧落，濯缨宁肯问沧浪。","他时得意交知仰，莫忘裁诗寄钓乡。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-08d3337f-92af-4eb3-821b-a963de44b079","tags":["庐山"]},{"id":"poem-f821236aaa61c88d9e15168e","title":"玉连环・解连环·流水细通何处","author":"王之道","dynasty":"宋","verses":["流水细通何处。","柳溪新雨。","清风十里送篮舆，行不尽、山无数。","一簇楼台窣堵。","老僧常住。","悬知俗客不曾来，门外苍苔如许。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-134","tags":[]},{"id":"poem-f82fd954723a94a13af94afd","title":"偈颂十二首  其一一","author":"释原妙","dynasty":"宋","verses":["学道如初不变心，千魔万难愈惺惺。","直须敲出虚空髓，拔却金刚脑后钉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-9ce58cf7-3c2a-4faf-bb56-f0bd4ff3ae14","tags":[]},{"id":"poem-f84151fe4a48472acc6e1f1e","title":"离伏龙","author":"陈造","dynasty":"宋","verses":["北风鏖屯云，倦鸟白昼迷。","筛为县麻雨，寒气晚凄凄。","何以赠行客，去路一尺泥。","卒徒淖莫前，草棘取新蹊。","可能辞滞留，十步九颠𬯀。","穷我恐非天，问子谁见挤。","少日忧患海，有眉未肯低。","流年况衰病，纵死非孩提。","戚欣何足云，寿夭久已齐。","秀色浮岭路，清音淙上溪。","会心各姿态，捋须忘惨凄。","山灵不无情，斩新献诗题。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-dca21bb1-0e47-4395-8bd7-041957c4f28e","tags":[]},{"id":"poem-f843fd2e86d907becfb9af4e","title":"偈颂（幷序○序为南岳齐己撰） 六","author":"居遁","dynasty":"唐","verses":["学道先须息万机，将机学道转生疑。","此门广大无遮障，学者虽多达者稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-abb8162f-b3ee-4520-9c54-eaacab1e7e33","tags":["衡山"]},{"id":"poem-f851efb6b6fdf76c4060f517","title":"潭上作","author":"张乔","dynasty":"唐","verses":["竹岛残阳映翠微，雪翎禽过碧潭飞。","人间未有关身事，每到渔家不欲归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2617d2ea-5a0f-4485-b0cf-07203461453d","tags":[]},{"id":"poem-f85cdc53d5be20082726f029","title":"字字双","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净上］试官没眼他及第，得志。","恋着相府多荣贵，入赘。","不思贫窘弃前妻，忘义。","叵耐穷酸太无知，呕气。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8192","tags":[]},{"id":"poem-f85fdb463f175a5c5732b2d2","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)告娘行听咨启，望娘行免泪零。","若不娶绣英，怎得我身荣？将彩凰冠来取你，取你到京中做一品夫人。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8992","tags":[]},{"id":"poem-f86d45b7c1c10e5fdc1815d8","title":"横吹曲辞 出塞","author":"窦威","dynasty":"唐","verses":["匈奴屡不平，汉将欲纵横。","看云方结阵，却月始连营。","潜军度马邑，扬斾掩龙城。","会勒燕然石，方传车骑名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-095c38dc-90fd-452f-812f-7dbf7c5662a2","tags":[]},{"id":"poem-f86ff6711a3b8a160cdcb200","title":"有瞽","author":"佚名","dynasty":"先秦","verses":["有瞽有瞽，在周之庭。设业设虡，崇牙树羽。应田县鼓，鞉磬柷圉。既备。","乃奏，箫管备举。喤喤厥声，肃雍和鸣，先祖是听。我客戾止，永观厥成。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-279","tags":[]},{"id":"poem-f87e671e4623524100549369","title":"塞上曲","author":"裴说","dynasty":"唐","verses":["极目望空阔，马羸程又赊。","月生方见树，风定始无沙。","楚水辞鱼窟，燕山到雁家。","如斯名利役，争不老天涯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-126d88a2-367a-45c0-b8ab-160868b02fe4","tags":["边塞"]},{"id":"poem-f898a52ff353c44af92b860d","title":"挂冠  其一","author":"李瓘","dynasty":"宋","verses":["古云学古斯入官，我见学易而官难。","平生透破梦觉关，本来面目只儒酸。","吾亲不侍若为欢，不如归去卧林间。","殿前三策沥忠肝，多谢皇恩天地宽。","戏衫卸下白衣还，扁舟飞过子陵滩。","前修亦有逋与抟，圣世与之俱空闲。","何物种放太厚颜，山鬼移文伐其奸。","此行无复出闽山，休音息影谷之盘。","今朝酾酒酹雩坛，便向钱塘门挂冠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-beacfd01-7ec0-4b67-b3bb-bcc813204987","tags":[]},{"id":"poem-f89e63c312fef1a3d691b64c","title":"关雎","author":"佚名","dynasty":"先秦","verses":["关关雎鸠，在河之洲。窈窕淑女，君子好逑。","参差荇菜，左右流之。窈窕淑女，寤寐求之。","求之不得，寤寐思服。悠哉悠哉，辗转反侧。","参差荇菜，左右采之。窈窕淑女，琴瑟友之。","参差荇菜，左右芼之。窈窕淑女，钟鼓乐之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-0","tags":[]},{"id":"poem-f89ea755de169c55214f9037","title":"题花光梅十首 高下随宜","author":"王柏","dynasty":"宋","verses":["亚水凌空任短长，枝枝风度要平章。","一樽月下吞花影，剔在须头点点香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-f70137d3-d1f3-4470-bf13-0a0e218e8b2b","tags":[]},{"id":"poem-f8a25080c7ece28a0ba1356e","title":"双声子","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(旦)结交的，结交的，待他恩深厚。","急请来，急请来，到此移尸首。","(合)莫停留，莫停留，便去休，便去休，拖尸首葬了，免惹忧愁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1895","tags":[]},{"id":"poem-f8ae61025df0df8075a36978","title":"春日杂兴十五首  其八","author":"华镇","dynasty":"宋","verses":["虚怀湛秋水，拳石枕寒沙。","上栽九节蒲，依倚复欹斜。","寄怀曲几稳，发秀终年嘉。","细根散苍髯，巨柢蟠青蛇。","玉篦莹故叶，剑铓长新芽。","融怡谢阳光，滋泽非露华。","洁贞宛相适，吹嘘曾不赊。","乃知元气游，脗合大道涯。","生生无间断，在在均迩遐。","阴骘有异禀，朗应无尔差。","故兹灵药材，见重长年家。","宁如溱洧赠，复异洛阳花。","臭腐荐高腴，夭冶扬芬葩。","栽培剧雕楮，徂谢迅飞霞。","韶光瞬息移，不得延豪奢。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-c48d5832-7263-46ca-a011-c00bd12193c5","tags":[]},{"id":"poem-f8b8610fadb487298b64b978","title":"八哀诗 赠秘书监江夏李公邕","author":"杜甫","dynasty":"唐","verses":["长啸宇宙间，高才日陵替。","古人不可见，前辈复谁继。","忆昔李公存，词林有根柢。","声华当健笔，洒落富清制。","风流散金石，追琢山岳锐。","情穷造化理，学贯天人际。","干谒走其门，碑版照四裔。","各满深望还，森然起凡例。","萧萧白杨路，洞彻宝珠惠。","龙宫墖庙涌，浩劫浮云卫。","宗儒俎豆事，故吏去思计。","眄睐已皆虚，跋涉曾不泥。","向来映当时，岂独劝后世。","丰屋珊瑚钩，骐𬴊织成罽。","紫骝随劒几，义取无虚岁。","分宅脱骖间，感激怀未济。","众归赒给美，摆落多藏秽。","独步四十年，风听九臯唳。","呜呼江夏姿，竟掩宣尼袂。","往者武后朝，引用多宠嬖。","否臧太常议，面折二张势。","衰俗凛生风，排荡秋旻霁。","忠贞负冤恨，宫阙深旒缀。","放逐早联翩，低垂困炎厉。","日斜𫛳鸟入，魂断苍梧帝。","荣枯走不暇，星驾无安税。","几分汉廷竹，夙拥文侯[篲]。","终悲洛阳狱，事近小臣敝。","祸阶初负谤，易力何深哜。","伊昔临淄亭，酒酣托末契。","重敍东都别，朝阴改轩砌。","论文到崔苏，指尽流水逝。","近伏盈川雄，未甘特进丽。","是非张相国，相扼一危脆。","争名古岂然，键捷歘不闭。","例及吾家诗，旷怀埽氛翳。","慷慨嗣真作，咨嗟玉山桂。","钟律俨高悬，鲲鲸喷迢遰。","坡陀青州血，芜没汶阳瘗。","哀赠竟萧条，恩波延揭厉。","子孙存如线，旧客舟凝滞。","君臣尚论兵，将帅接燕蓟。","郎吟六公篇，忧来豁蒙蔽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-03733be3-cf7c-442c-b6ce-9918b9aa57ac","tags":[]},{"id":"poem-f8b87ad2b43a5eec2c8ea6d9","title":"送耿拾遗𣲗充括图书使往江淮","author":"卢纶","dynasty":"唐","verses":["传令收遗籍，诸儒喜饯君。","孔家唯有地，禹穴但生云。","编简知还续，虫鱼亦自分。","如逢北山隐，一为谢移文。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-02bb777a-fa66-4121-9551-be32bea452df","tags":[]},{"id":"poem-f8bc92efb084ee06aeefe229","title":"松石  其一","author":"刘跂","dynasty":"宋","verses":["笔端陶冶不无神，纸面流沙秋后云。","点破沙痕便成水，一溪松石浪沄沄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-dfdd70c3-51aa-4ebc-8b63-30a047f0e38e","tags":[]},{"id":"poem-f8c5ff268290d5d91a422cf1","title":"寄王荆公忆江阴","author":"朱明之","dynasty":"宋","verses":["城上城隍古镜中，城边山色翠屏风。","鱼虾接海随时足，稻米连湖逐岁丰。","太伯人民堪教育，春申沟港可疏通。","朱轮天使从君欲，异日能忘笑语同。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-71cfd4a2-5179-4927-858f-45b4587fdf5d","tags":[]},{"id":"poem-f8c90b1ba7be5cb05829999e","title":"帝京篇十首 七","author":"太宗皇帝","dynasty":"唐","verses":["落日双阙昏，回舆九重暮。","长烟散初碧，皎月澄轻素。","搴幌玩琴书，开轩引云雾。","斜汉耿层阁，清风摇玉树。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-621207da-c9ba-4f95-b637-a6bef91b1411","tags":[]},{"id":"poem-f8cd39b8ac86f0ad8932e7ee","title":"偈颂七十一首  其六二","author":"释了惠","dynasty":"宋","verses":["星在天上，眼在眉下。","星无暗明，眼无昼夜。","密密绵绵无缝罅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-debff62a-a3f9-47b0-8187-bde95a4e8d8e","tags":[]},{"id":"poem-f8df3e87ae00f2b6da649c32","title":"去矣行","author":"杜甫","dynasty":"唐","verses":["君不见鞲上鹰，一饱则飞掣。","焉能作堂上燕，衔泥附炎热。","野人旷荡无腼颜，岂可久在王侯间。","未试囊中餐玉法，明朝且入蓝田山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ba4bd65a-2c56-4f81-b0bf-dacc0068c271","tags":[]},{"id":"poem-f8e9e28ca7453fa68de04683","title":"枫桥夜泊","author":"张继","dynasty":"唐","verses":["月落乌啼霜满天，江枫渔火对愁眠。","姑苏城外寒山寺，夜半钟声到客船。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-楓橋夜泊","tags":[]},{"id":"poem-f8efaefac806f40780a7f03c","title":"如梦令·花落莺啼春暮","author":"谢逸","dynasty":"宋","verses":["花落莺啼春暮。","陌上绿杨飞絮。","金鸭晚香寒，人在洞房深处。","无语。","无语。","叶上数声疏雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-616","tags":[]},{"id":"poem-f8f85bccdf43cb48309850f9","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我孩儿不须挂牵，爹只望孩儿贵显。","若得你名登高选，(合)须早把信音传，须早把信音传。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4948","tags":[]},{"id":"poem-f904dafd780ac3430e4e3b5c","title":"渔家傲·别恨长长欢计短","author":"欧阳修","dynasty":"宋","verses":["别恨长长欢计短。","疏锺促漏真堪怨。","此会此情都未半。","星初转。","鸾琴凤乐匆匆卷。","河鼓无言西北盼。","香蛾有恨东南远。","脉脉横波珠泪满。","归心乱。","离肠便逐星桥断。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-661","tags":[]},{"id":"poem-f9083de9ad67405e9682b1b1","title":"示如梦禅人行脚","author":"释原妙","dynasty":"宋","verses":["闲处休居静莫住，转入转深转幽固。","纵至深深尽底时，更须知有那一步。","昔日曹溪亲到来，今时往往多差互。","若非丧尽目前机，倒岳倾湫无觅处。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ee6988be-0945-4694-999f-d87a3d740d40","tags":[]},{"id":"poem-f9158393d64dd6da2d2f56f6","title":"句 二","author":"江为","dynasty":"唐","verses":["城头初角送残晖。","（《江湖小集》卷六绍嵩《江浙纪行集句诗》引）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-c53d7e4f-3e10-4014-bb81-301b9260e338","tags":[]},{"id":"poem-f925353e14deec83fb39e4b6","title":"冬日骆家亭子","author":"刘得仁","dynasty":"唐","verses":["亭台腊月时，松竹见贞姿。","林积烟藏日，风吹水合池。","恨无人此住，静有鹤相窥。","是景吟诗徧，真于野客宜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-701ddaac-fd35-42ee-88e2-1da8d56e9a62","tags":[]},{"id":"poem-f9268f22e73f75c3678da9e5","title":"水调歌头·太白乃吾祖","author":"李纲","dynasty":"宋","verses":["太白乃吾祖，逸气薄青云。","开元有道，聊复乘兴一来宾。","天子呼来方醉，洒面清泉微醒，馀吐试龙巾。","词翰不加点，歌阕满宫春。","笔风雨，心锦绣，极清新。","大儿中令，神契兼有坐忘人。","不识将军高贵，醉里指污吾足，乃敢尚衣嗔。","千载已仙去，图象耸风神。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-573","tags":[]},{"id":"poem-f92e6653115a4d01bfe98c40","title":"玉楼春·西亭饮散清歌阕","author":"欧阳修","dynasty":"宋","verses":["西亭饮散清歌阕。","花外迟迟宫漏发。","涂金烛引紫骝嘶，柳曲西头归路别。","佳辰只恐幽期阔。","密赠殷勤衣上结。","翠屏魂梦莫相寻，禁断六街清夜月。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-667","tags":[]},{"id":"poem-f9338cf60f07ed5c9e1f5b11","title":"有狐","author":"佚名","dynasty":"先秦","verses":["有狐绥绥，在彼淇梁。心之忧矣，之子无裳。","有狐绥绥，在彼淇厉。心之忧矣，之子无带。","有狐绥绥，在彼淇侧。心之忧矣，之子无服。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-62","tags":[]},{"id":"poem-f93b4b435ad42dfb5089c606","title":"幺","author":"杨景贤","dynasty":"元","verses":["拣着这竹径花溪阴处走，则着他柳影松斜深处有。","休烦恼莫惭羞，黄昏时候，休着我和月倚南楼。","(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4494","tags":[]},{"id":"poem-f93c213ded4478bb0e9b9dca","title":"酬从叔听夜泉见寄","author":"项斯","dynasty":"唐","verses":["梦罢更开户，寒泉声隔云。","共谁寻最远，独自坐偏闻。","岩际和风滴，溪中泛月分。","岂知当此夜，流念到江𣸣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-bfc964a8-833a-4adf-9adf-d985da800e8c","tags":[]},{"id":"poem-f94722b05a7f136511afc614","title":"梅花落","author":"纳兰性德","dynasty":"清","verses":["春色凤城来，寒梅逼岁开。","条风初入树，缥雪渐侵苔。","粉逐莺衣散，香黏蝶翅回。","陇头人未返，急管莫频催。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-239","tags":[]},{"id":"poem-f947815fd958ff8871962eee","title":"江南杂题三十首 其六","author":"张祜","dynasty":"唐","verses":["远郭浸烟波，村桥入薜萝。","水虵惊去疾，山鸟自来多。","夜月倾壶酒，春风就榜歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9e4d77a9-311d-4ce8-accf-a54a1ff648dc","tags":[]},{"id":"poem-f94a684c37c43f520516e751","title":"浣溪沙·红藕香寒翠渚平","author":"顾敻","dynasty":"五代","verses":["红藕香寒翠渚平，月笼虚阁夜蛩清，塞鸿惊梦两牵情。","宝帐玉炉，残麝冷，罗衣金缕暗尘生，小窗孤烛泪纵横。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-1","tags":[]},{"id":"poem-f952ba8d2d29ce0efb1f5ff2","title":"送魏端公入朝","author":"孟郊","dynasty":"唐","verses":["东洛尚淹玩，西京足芳妍。","大宾威仪肃，上客冠劒鲜。","岂惟空恋阙，亦以将朝天。","局促尘末吏，幽老病中弦。","徒怀青云价，忽至白发年。","何当补风教，为荐三百篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ac0730d6-7a27-4321-83bd-f10fb7eda52c","tags":[]},{"id":"poem-f953c94eb2b293eea481c4c6","title":"送瑞莲新米白酒与韩监仓","author":"陈造","dynasty":"宋","verses":["珍珠滴红敌紫腴，君家宝此如珍珠。","我家玉友亦胜友，论交遣到君座隅。","秋莲结实甘胜蜜，香粳荐新玉为粒。","遥知毫末不及宾，一笑聊同孟光吃。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8fb94340-55d2-4a06-8c98-ff4ff730e489","tags":[]},{"id":"poem-f9561289b442e2361936d6b5","title":"西江月·滴滴金盘露冷","author":"谢逸","dynasty":"宋","verses":["滴滴金盘露冷，萧萧玉宇风清。","长庚入梦晓窗明。","淡月微云耿耿。","松竹五峰秋色，笙歌三市欢声。","华堂开宴拥娉婷。","天上人间共庆。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-606","tags":[]},{"id":"poem-f957975cca39f854813470f5","title":"郊庙歌辞 德明兴圣庙乐章 迎神","author":"李舒","dynasty":"唐","verses":["元尊九德，佐尧光宅。","烈祖太宗，方周作伯。","响怀霜露，乐变金石。","白云清风，髣髴来格。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-3d290e33-710f-4419-a30d-2d76a3b3e54a","tags":[]},{"id":"poem-f9583a8e9f24cbcb61799257","title":"那","author":"佚名","dynasty":"先秦","verses":["猗与那与！置我鞉鼓。奏鼓简简，衎我烈祖。汤孙奏假，绥我思成。","鞉鼓渊渊，嘒嘒管声。既和且平，依我磬声。于赫汤孙！穆穆厥声。","庸鼓有斁，万舞有奕。我有嘉客，亦不夷怿。自古在昔，先民有作。","温恭朝夕，执事有恪，顾予烝尝，汤孙之将。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-300","tags":[]},{"id":"poem-f9636e4588892544f2c27126","title":"次韵张守阻冰","author":"陈造","dynasty":"宋","verses":["清篇方鼎来，强韵不可柰。","胆掉久未定，如守上泷柂。","浑厚出绮丽，平谈含顿挫。","正始叹不嗣，黄初君突过。","想当舟陷泥，势若右旋磨。","河神要好句，待君颜一破。","我行阻重坝，倍费客炊火。","邗沟尘欲扬，人步沟尾汊。","一雨濯旱枯，此惠谁所假。","生世天不人，孰者可吊贺。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-09b22afc-8319-4770-8560-e6a357dd28f7","tags":[]},{"id":"poem-f96c771eb245d1aea8292809","title":"泊凫矶江馆","author":"赵嘏","dynasty":"唐","verses":["风雪晴来岁欲除，孤舟晚下意何如。","月当轩色湖平后，雁断云声夜起初。","傍晓管弦何处静，犯寒杨柳遶津疎。","三间茅屋东溪上，归去生涯竹与书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-bd05ebbd-fe4d-4a79-9758-bcacf6d63d3c","tags":[]},{"id":"poem-f96f9d484cc741aed55dc2ca","title":"扈从登封途中作","author":"宋之问","dynasty":"唐","verses":["帐殿郁崔嵬，仙游实壮哉！","晓云连幕卷，夜火杂星回。","谷暗千旗出，山鸣万乘来。","扈从良可赋，终乏掞天才。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-扈從登封途中作","tags":[]},{"id":"poem-f974f36144482e4ef562d84f","title":"蝶恋花·一望瑶华初委地","author":"黄裳","dynasty":"宋","verses":["一望瑶华初委地。","更约幽人，共赏岩边翠。","拭把方诸聊与试。","无情争得无中泪。","飞瀑恐从星汉至。","渐向宾筵，但觉寒如水。","自爱一轮方得意。","轻随箕毕还成累。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-639","tags":[]},{"id":"poem-f97b31ec46db3b42e9afe596","title":"酒泉子·记得去年","author":"牛峤","dynasty":"五代","verses":["记得去年，烟暖杏园。","花正发，雪飘香，江草绿，柳丝长。","钿车纤手卷帘望，眉学春山样。","凤钗低袅翠鬟上，落梅妆。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-21","tags":[]},{"id":"poem-f97d6f000d8b1fe97da813f5","title":"柏舟","author":"佚名","dynasty":"先秦","verses":["泛彼柏舟，在彼中河。髧彼两髦，实维我仪。之死矢靡它。母也天只，不谅人只！","泛彼柏舟，在彼河侧。髧彼两髦，实维我特。之死矢靡慝。母也天只，不谅人只！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-44","tags":[]},{"id":"poem-f97e219be063795ee5e59669","title":"赠张敬微","author":"蔡希寂","dynasty":"唐","verses":["大河东北望桃林，杂树冥冥结翠阴。","不知君作神仙尉，特讶行来云雾深。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-210e4b4a-f6b8-4761-8dba-9e3ff50293d8","tags":[]},{"id":"poem-f980be8f4acdaab540a0bbb2","title":"奉礼歌·吹葭缇龠气潜分","author":"洪适","dynasty":"宋","verses":["吹葭缇龠气潜分。","云采宜书壤效珍。","长日至，一阳新。","四时玉烛和匀。","物欣欣。","造化转洪钧。","郊之祭，孤竹管，六变舞云门。","自古严禋。","牺牲具，粢盛洁，豆笾陈。","衮龙陟降，币玉纷纶。","彻高阍。","灵之斿，神哉沛，排历昆仑。","九歌毕，盈郊瞻槱燎，斗转参横将旦，天开地辟如春。","清跸移轮。","阗然鼓吹相闻。","𥬞祥云。","欢胪八陛，厘逆三神。","圣矣吾君。","华封祝、慈宫万寿，椒掖多男，六合同文。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-775","tags":[]},{"id":"poem-f986bf2ffd9f4101f69aa54c","title":"三日独坐驩州思忆旧游","author":"沈佺期","dynasty":"唐","verses":["两京多节物，三日最遨游。","丽日风徐卷，香尘雨暂收。","红桃初下地，绿柳半垂沟。","童子成春服，宫人罢射鞲。","禊堂通汉苑，解席绕秦楼。","束皙言谈妙，张华史汉遒。","无亭不驻马，何浦不横舟。","舞籥千门度，帷屏百道流。","金丸向鸟落，芳饵接鱼投。","濯秽怜清浅，迎祥乐献酬。","灵刍陈欲弃，神药曝应休。","谁念招魂节，翻为御魅囚。","朋从天外尽，心赏日南求。","铜柱威丹徼，朱崖镇火陬。","炎蒸连晓夕，瘴疠满冬秋。","西水何时贷？南方讵可留。","无人对炉酒，宁缓去乡忧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d694744e-af07-4de8-98c9-2bd1936db3bb","tags":[]},{"id":"poem-f9890c25eca416f0438ad2ad","title":"送淡公 十一","author":"孟郊","dynasty":"唐","verses":["牵师袈裟别，师断袈裟归。","问师何苦去，感吃言语稀。","意恐被诗饿，欲住将底依。","卢殷刘言史，饿死君已噫。","不忍见别君，哭君他是非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-a5da13b9-e54d-4b4f-a1e7-cb1723cd2edf","tags":[]},{"id":"poem-f9a06cbc87b2f8082ecb2127","title":"青玉案·三年枕上吴中路","author":"蒋璨","dynasty":"宋","verses":["三年枕上吴中路。","遣黄耳、随君去。","欲过松江呼小渡。","莫惊鸥鹭，四桥都是，老子经行处。","辋川图上看春暮。","长忆高人右丞句。","作个归期天未许。","春衫犹是，小蛮针线，曾湿西湖雨。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-983","tags":["西湖"]},{"id":"poem-f9a970b48135f0dd88a31236","title":"浣溪沙·湿翠湖山收晚烟","author":"史浩","dynasty":"宋","verses":["湿翠湖山收晚烟。","月华如练水如天。","兴来催上钓鱼船。","青箬一尊汀草畔，霜筠数曲渚花边。","更于何处觅神仙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-157","tags":[]},{"id":"poem-f9aaf507345873a6549c8dea","title":"荷叶杯·记得那时相见","author":"顾敻","dynasty":"五代","verses":["记得那时相见，胆战。","鬓乱四肢柔，泥人无语不抬头。","羞么羞，羞么羞。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-24","tags":[]},{"id":"poem-f9b60c959a846fcd3e0d62ac","title":"霁后寄白阁僧","author":"马戴","dynasty":"唐","verses":["苍翠霾高雪，西峰鸟外看。","久披山衲坏，孤坐石床寒。","盥手水泉滴，燃灯夜烧残。","终期老云峤，煮药伴中餐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-806a5f89-fd88-43ea-a54d-3b277fec0e11","tags":[]},{"id":"poem-f9b8e3c7c1da8192c7962d6a","title":"和吴可权长官","author":"廖正一","dynasty":"宋","verses":["士元应展骥，百里聊尔绊。","函继三异声，江述凭东观。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-d411c784-286b-4408-adbc-bcbe7f37cd5c","tags":[]},{"id":"poem-f9c8863826bc2bec87277a25","title":"别卢使君","author":"贯休","dynasty":"唐","verses":["杜宇声声急，行行楚水𣸣。","道无裨政化，行处傲孤云。","幸到膺门下，频蒙俸粟分。","诗虽曾引玉，棋数中埋军。","山好还寻去，恩深岂易云。","扇风千里泰，车雨九重闻。","晴雾和花气，危樯鼓浪文。","终期陶铸日，再见信陵君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-da1b470e-721b-44fa-a2a4-96d9be93a197","tags":[]},{"id":"poem-f9ccb7d9d8c4f772f68cb1c0","title":"和陈处士在雍丘见寄","author":"徐铉","dynasty":"宋","verses":["衰薄喜多幸，退公谁与闲。","高人乘兴去，相望两程间。","卷箔有微雪，登楼无远山。","清谈胜题赠，何日杖藜还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-b02c146e-45a8-4289-a469-410b4498945e","tags":[]},{"id":"poem-f9d0be111c1a512e827b97c8","title":"诗寄赠四明宝云通法师（二首） 二","author":"钱俶","dynasty":"唐","verses":["相望几千里，旷然违道情。","自兹成乍别，疑是隔浮生。","得旨探玄寂，无心竞利名。","苑斋正秋夜，谁伴诵经声。","（见《大正新修大藏经》第四六册南宋释宗晓编《宝云振祖集》。","）（按：此诗题下署「吴越国王钱俶」，末附嘉泰壬戌宗晓跋，叙得诗始末，文长不具录。","通法师卒于宋太宗端拱改元之年，年六十三。","俶作此诗时已降宋否，尚难考详。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-0233493d-ee69-426c-891b-ce2909ea2be0","tags":[]},{"id":"poem-f9d98d0eb88520a6fb2b061a","title":"乌夜啼","author":"聂夷中","dynasty":"唐","verses":["众鸟各归枝，乌乌尔不栖。","还应知妾恨，故向绿窗啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-f7763540-977d-4290-8d99-2e0ad16af9d6","tags":[]},{"id":"poem-f9e430f66395e9eae50c0976","title":"送周郎中还司","author":"徐铉","dynasty":"宋","verses":["忆在庐山始识君，当时惟拟共眠云。","那知身计关前定，却向人间逐世纷。","紫阁峰前欣独往，银台门里叹离群。","青囊旧有登真诀，莫遣闲人取次闻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-7cd1cc4c-e7d5-4449-b615-e1f0d8ffc57e","tags":["庐山"]},{"id":"poem-f9e605a80a881cd63622e0e3","title":"宴桃源・如梦令·天气把人僝僽","author":"黄庭坚","dynasty":"宋","verses":["天气把人僝僽。","落絮游丝时候。","茶饭可曾忺，镜中赢得销瘦。","生受。","生受。","更被养娘催绣。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-807","tags":[]},{"id":"poem-f9e7267d77e345ff0dc4f448","title":"马嵬感事","author":"唐求","dynasty":"唐","verses":["冷气生深殿，狼星渡远关。","九城鼙鼓内，千骑道途间。","凤髻随秋草，銮舆入暮山。","恨多留不得，悲泪满龙颜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-1f12e4d4-7d21-47f0-9ce9-469675b1da62","tags":[]},{"id":"poem-f9e7d9d1f8a76df27b967f8f","title":"浣溪沙·楼上晴天碧四垂","author":"周邦彦","dynasty":"宋","verses":["楼上晴天碧四垂。","楼前芳草接天涯。","劝君莫上最高梯。","新笋已成堂下竹，落花都上燕巢泥。","忍听林表杜鹃啼。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-383","tags":[]},{"id":"poem-f9e8015f681c113a7387befa","title":"暮春即事","author":"王镃","dynasty":"宋","verses":["卖花声断雨蒙蒙，怯酒情怀易得中。","燕子自来还自去，胭脂吹老海棠风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a76ac947-ce86-4650-a272-c9bc0beb4620","tags":[]},{"id":"poem-f9f44e9480a7f91336e43e2d","title":"颂古三十一首  其二○","author":"释原妙","dynasty":"宋","verses":["饥火炎炎烧断肠，亲逢王膳不能尝。","可怜并逐溪流去，百亿沧溟透底香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-95c35fa2-38a2-442d-961c-f85fbff3b13b","tags":[]},{"id":"poem-f9f8b80c6b8a6730ff0c8e32","title":"奉和中书舍人贾至早朝大明宫","author":"岑参","dynasty":"唐","verses":["鸡鸣紫陌曙光寒，莺啭皇州春色阑。","金阙晓钟开万户，玉阶仙仗拥千官。","花迎劒珮星初落，柳拂旌旗露未干。","独有凤皇池上客，阳春一曲和皆难。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-8df8e94b-ffe4-4930-af4c-491d7cb04651","tags":["唐诗三百首","七言律诗","唱和"]},{"id":"poem-fa0458ed668d75a8baf84bc3","title":"林主簿明仲挽词  其一","author":"王十朋","dynasty":"宋","verses":["齿德尊乡党，匈中有古今。","箕裘传蕴藻，臧否判崔林。","呼佛知仁政，名轩见道心。","扁舟欲访戴，仙去不容寻。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-e917cec5-ab87-40e7-b7da-1ef94e525737","tags":[]},{"id":"poem-fa057801784f3a9b2411bc49","title":"元日云安道","author":"赵崇嶓","dynasty":"宋","verses":["元日度巴云，时逢朐䏰人。","野梅空自落，山鸟暗知春。","不醉新年酒，徒悲异域身。","无穷倦行意，亭柳漫风尘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c462065d-296d-433d-b152-dee62f307307","tags":[]},{"id":"poem-fa0d4324106bcbaa4ffef1f3","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["卑人欲往京畿，从早间等到今时。","妇人爱酒贪欢喜，终久后又成何济？想起，这妇人害了我家计。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2581","tags":[]},{"id":"poem-fa0e221605f4435d4381eb47","title":"苦雪四首 一","author":"高适","dynasty":"唐","verses":["二月犹北风，天阴雪冥冥。","寥落一室中，怅然慙百龄。","苦愁正如此，门柳复青青。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3e598395-2064-42df-ae7a-16bf591c0695","tags":[]},{"id":"poem-fa199117de20a391f8e06015","title":"失调名·水团冰浸砂糖裹","author":"张耒","dynasty":"宋","verses":["水团冰浸砂糖裹。","有透明角黍松儿和。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-352","tags":[]},{"id":"poem-fa2181f9b4d65c9dbecc66a1","title":"长相思·一重山","author":"纳兰性德","dynasty":"清","verses":["一重山，两重山，山远天高烟水寒，相思枫叶丹。","菊花开，菊花残，塞雁高飞人未还，一帘风月闲。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-195","tags":[]},{"id":"poem-fa259b8251cececec766dde8","title":"祈父","author":"佚名","dynasty":"先秦","verses":["祈父，予王之爪牙。胡转予于恤，靡所止居？","祈父，予王之爪士。胡转予于恤，靡所厎止？","祈父，亶不聪。胡转予于恤？有母之尸饔。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-184","tags":[]},{"id":"poem-fa3a9fe7641c0f38cef0db05","title":"句","author":"刘赞","dynasty":"唐","verses":["絮花飞起雪漫漫，长得宫娥带笑看。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2dacb6eb-7a73-482c-9d02-aedecfd386f0","tags":[]},{"id":"poem-fa409303c1fa9763820ae558","title":"燕归梁·绰约彤霞降紫霄","author":"赵鼎","dynasty":"宋","verses":["绰约彤霞降紫霄。","是仙子风标。","湘裙明佩响琼瑶。","散馥郁、暗香飘。","小春十月寒犹浅，妆粉弄梅梢。","秦楼风月待吹箫。","舞双鹤、醉蟠桃。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-945","tags":[]},{"id":"poem-fa448ffcc4cc4376868f0efb","title":"送从弟彻东归","author":"张籍","dynasty":"唐","verses":["缑山领印知公奏，才称同时尽不如。","奉使贺成登册礼，陪班看出降恩书。","去回在路秋尘里，受诏辞归晓漏初。","早晚得为朝署拜，闲坊买宅作邻居。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-77b0962f-1c31-4ff1-9f4c-2f90d4cd309c","tags":[]},{"id":"poem-fa4616b0db0ad0a40b04bdcf","title":"荔枝五首  其四","author":"李纲","dynasty":"宋","verses":["荔子蛮方也自丹，不如闽岭为微酸。","玉盘磊珂三千颗，犹忆甘芳绕齿寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-ec50e74c-3c68-4e65-b2e7-ab9b2e8e1793","tags":[]},{"id":"poem-fa6441a2c2f531a617e48f9f","title":"拙斋","author":"释居简","dynasty":"宋","verses":["大巧曾闻窃得灵，主司关籥镇随身。","巧还有尽无如拙，却笑天孙未识真。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-41c3c913-ed1c-4837-a96c-f0244016f29d","tags":[]},{"id":"poem-fa69a802d3c3d29824592bb1","title":"木瓜","author":"佚名","dynasty":"先秦","verses":["投我以木瓜，报之以琼琚。匪报也，永以为好也！","投我以木桃，报之以琼瑶。匪报也，永以为好也！","投我以木李，报之以琼九。匪报也，永以为好也！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-63","tags":[]},{"id":"poem-fa69acd1ac9b335da7fea52c","title":"残莺","author":"雍裕之","dynasty":"唐","verses":["花阑莺亦嬾，不语似含情。","何言百啭舌，唯余一两声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-88820d3f-9dd5-44d6-9856-1f6c71aaa5c9","tags":[]},{"id":"poem-fa6b43ea7aa0f8102478ef2e","title":"秋夜闻郑山人弹楚妃怨","author":"鲍溶","dynasty":"唐","verses":["明月摇落夜，深堂清净弦。","中间楚妃奏，十指哀婵娟。","寥寥夜含风，荡荡意如泉。","寂寞物无象，依稀语空烟。","旅人多西望，客鴈难南前。","由来感神事，岂为无情传。","容华能几时，不再来者年。","此夕河汉上，双星含凄然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ba88d0d2-683d-4e0d-904d-98dc638afa1e","tags":[]},{"id":"poem-fa6eedb19d9c042efe67a786","title":"望江南・忆江南·清昼永","author":"李纲","dynasty":"宋","verses":["清昼永，幽致夏来多。","远岸参差风扬柳，平湖清浅露翻荷。","移棹钓烟波。","凉一霎，飞雨洒轻蓑。","满眼生涯千倾浪，放怀乐事一声歌。","不醉欲如何。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-583","tags":[]},{"id":"poem-fa7ad95319337c72af029f50","title":"圣小儿诗","author":"贺德英","dynasty":"宋","verses":["英秀钟河岳，生来号圣儿。","虽云年尚小，不待学而知。","博古通今识，超群迈秀姿。","浩然食牛气，非若聚鱼嬉。","祖莹耽书日，甘罗入相时。","看看头角长，身到凤凰池。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-3519c7d8-3172-495b-a102-8eba82429b7b","tags":[]},{"id":"poem-fa7ca67b692a840a1a2e221f","title":"古镜歌三首 一","author":"泰钦","dynasty":"唐","verses":["尽道古镜不曾见，借你时人看一徧。","目前不覩一纤豪，湛湛冷光凝一片。","凝一片，无背面，嫫母临妆不称情，潘生回首频嘉叹。","何欣欣，何戚戚，好丑由来那个是（《大正藏》本作「从来那是的」）？","只遮是，转沈醉，演若晨窥怖走时，子细思量还有以。","我问颠狂不暂回，泪流向予声哀哀。","哽咽未能申吐得，你头与影悠悠哉！悠悠哉，尔许多时那里来？","迷云开，行行携手上高台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-427b62e2-ae1c-4a2a-9121-35e13f333c36","tags":[]},{"id":"poem-fa7ea6ac3879c82e8bc8c396","title":"佛教梵文唵字唐玄宗书并读（原刻石在河南登封，还有御制《老子赞》。） 二","author":"唐明皇","dynasty":"唐","verses":["鹤立蛇形势未休，五尺文字鬼神愁。","儒门弟子无人识，穿耳胡僧笑点头。","（〖1〗现在根据最古的敦煌本补入，而把所知所见的石本刻本作为附录，以便参攷。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ee418f41-39c8-4cfa-ab8f-a94fcb09419b","tags":[]},{"id":"poem-fa839dccb46828b1d2448f93","title":"幺","author":"杨景贤","dynasty":"元","verses":["你若能尝佛子茶，胜参赵老惮。","休猜做金尊美酒斗十千，但得那世尊肯见。","恰敢着你即时回转，不须妙法再三言。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3393","tags":[]},{"id":"poem-fa88a6c868dd46ffae202aa9","title":"念奴娇·闹红一舸","author":"姜夔","dynasty":"宋","verses":["闹红一舸，记来时、尝与鸳鸯为侣。","三十六陂人未到，水佩风裳无数。","翠叶吹凉，玉容销酒，更洒菰蒲雨。","嫣然摇动，冷香飞上诗句。","日暮。","青盖亭亭，情人不见，争忍凌波去。","只恐舞衣寒易落，愁入西风南浦。","高柳垂阴，老鱼吹浪，留我花间住。","田田多少，几回沙际归路。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-129","tags":["宋词三百首"]},{"id":"poem-fa89c87bdda4e7e2ed99a1ac","title":"句","author":"扈蒙","dynasty":"宋","verses":["五凤齐飞入翰林。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-a83b6e27-3ab0-44da-9bd1-935864e53828","tags":[]},{"id":"poem-fa9d344ae0b60e9aec21c5cb","title":"送朱大入秦","author":"王维","dynasty":"唐","verses":["避人五陵去，宝剑值千金。","分手脱相赠，平生一片心。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送朱大入秦","tags":[]},{"id":"poem-fa9d4db5dae7f7ed90ee0a9c","title":"送远使","author":"张籍","dynasty":"唐","verses":["扬旌过陇头，陇水向西流。","塞路依山远，戍城逢笛秋。","寒沙阴漫漫，疲马去悠悠。","为问征行将，谁封定远侯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-9c8e7368-a276-45e8-99ea-c23474cf39ef","tags":[]},{"id":"poem-faa1b6aefeee62f86b84012c","title":"始见二毛","author":"鲍溶","dynasty":"唐","verses":["玄发迎忧光色阑，衰华因镜强相看。","百川赴海返潮易，一叶报秋归树难。","初弄藕丝牵欲断，又惊机素翦仍残。","颜生岂是光阴晚，余亦何人不自宽。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-9bb3ff12-7af7-4f58-b077-0e19a8a9b5ea","tags":[]},{"id":"poem-faa3a32543ae32ba16823937","title":"塞芦子","author":"杜甫","dynasty":"唐","verses":["五城何迢迢，迢迢隔河水。","边兵尽东征，城内空荆杞。","思明割怀卫，秀岩西未已。","回略大荒来，崤函盖虚尔。","延州秦北户，关防犹可倚。","焉得一万人，疾驱塞芦子。","岐有薛大夫，旁制山贼起。","近闻昆戎徒，为退三百里。","芦关扼两寇，深意实在此。","谁能叫帝阍，胡行速如鬼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cbebf2b4-fabb-4c07-b8bc-f2efcfe377ad","tags":[]},{"id":"poem-faa66127ecb3b86d42e156e0","title":"竹枝·门前春水白苹花","author":"孙光宪","dynasty":"五代","verses":["门前春水（竹枝）白苹花（女儿），岸上无人（竹枝）小艇斜（女儿）。","商女经过（竹枝）江欲暮（女儿），散抛残食（竹枝）饲神鸦（女儿）。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-33","tags":[]},{"id":"poem-faa958a29cd6bbb832413f6a","title":"送友人游东川","author":"喻坦之","dynasty":"唐","verses":["食尽须分散，将行几愿留。","春兼三月闰，人拟半年游。","风俗同吴地，山川拥梓州。","思君登栈道，猨啸始应愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-77576a34-b2d1-498e-9cfe-ea51f70c2083","tags":[]},{"id":"poem-faca05835c440cf206c9f2a7","title":"偈颂（幷序○序为南岳齐己撰） 十九","author":"居遁","dynasty":"唐","verses":["扫地煎茶及针把，更无余事可留心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-53094029-075b-4f61-8ab9-45e15a8f7db4","tags":["衡山"]},{"id":"poem-facab2fb6e4c655b3f511795","title":"西江月·体态看来隐约","author":"张先","dynasty":"宋","verses":["体态看来隐约，梳妆好是家常。","檀槽初抱更安详。","立向尊前一行。","小打登钩怕重，尽缠绣带由长。","娇春莺舌巧如簧。","飞在四条弦上。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-273","tags":[]},{"id":"poem-fad33a2f33b5b90ec2e3d50c","title":"郊庙歌辞 祀九宫贵神乐章 豫和 三","author":"不详","dynasty":"唐","verses":["帝临中坛，受厘元神。","皇灵萃止，羽旄肃陈。","摄提运衡，招摇移轮。","光光宇宙，电耀雷震。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7c3567ec-56b5-4ca3-be4a-0be999fa4cfa","tags":[]},{"id":"poem-fae01e71270eb8a5358ba12e","title":"谢池春·残寒销尽","author":"李之仪","dynasty":"宋","verses":["残寒销尽，疏雨过、清明后。","花径敛馀红，风沼萦新皱。","乳燕穿庭户，飞絮沾襟袖。","正佳时，仍晚昼。","著人滋味，真个浓如酒。","频移带眼，空只恁、厌厌瘦。","不见又思量，见了还依旧。","为问频相见，何似长相守。","天不老，人未偶。","且将此恨，分付庭前柳。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-47","tags":["宋词三百首"]},{"id":"poem-fae1ce6cddc9fd5672962d3d","title":"送周畏知二首  其一","author":"张栻","dynasty":"宋","verses":["秋冬仍苦雨，旬浃喜霜晴。","木末楼台见，江头橘柚明。","登临方适意，离别已增情。","后夜相思地，寒梅影正横。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-59a7a4b4-9ab6-49bb-9fce-c92e27a98ac8","tags":[]},{"id":"poem-fae407601d79fd2e22c49a72","title":"秋登兰山寄张五","author":"孟浩然","dynasty":"唐","verses":["北山白云里，隐者自怡悦。","相望试登高，心飞逐鸟灭。","愁因薄暮起，兴是清秋发。","时见归村人，沙行渡头歇。","天边树若荠，江畔舟如月。","何当载酒来，共醉重阳节。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-56ca5b29-4bb9-4f12-9200-6bc7c72e4e47","tags":["唐诗三百首","五言古诗","秋天","登高","山","怀人"]},{"id":"poem-faeb9ec1f7dadcf56d6b65d7","title":"庐陵九日","author":"李咸用","dynasty":"唐","verses":["菊花山在碧江东，冷酒清吟兴莫穷。","四十三年秋里过，几多般事乱来空。","虽惊故国音书绝，犹喜新知语笑同。","竟日开门无客至，笛声迢逓夕阳中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-41baaaab-186e-4e02-a509-04a280ff65ac","tags":[]},{"id":"poem-faef80efdaf5c59d23d13871","title":"温泉宫","author":"鲍溶","dynasty":"唐","verses":["忆昔开元天地平，武皇十月幸华清。","山蒸阴火云三素，日落温泉鸡一鸣。","彩羽鸟仙歌不死，翠霓童妾舞长生。","仍闻老叟垂黄发，犹说龙髯缥缈情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-739cdb6a-c48b-457b-b4aa-ea2ad0f0040d","tags":[]},{"id":"poem-faf4308ea4e7c4dafa3fd72e","title":"送陆员外","author":"王维","dynasty":"唐","verses":["郎署有伊人，居然古人风。","天子顾河北，诏书除征东。","拜手辞上官，缓步出南宫。","九河平原外，七国蓟门中。","阴风悲枯桑，古塞多飞蓬。","万里不见虏，萧条胡地空。","无为费中国，更欲邀奇功。","迟迟前相送，握手嗟异同。","行当对侯归，肯访商山翁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-7762fa57-7362-4dc5-ac5f-dbae7b4db5aa","tags":[]},{"id":"poem-fb0ab056ec95907daad4807b","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["婆婆暗自喜，得你嫁夫婿。","图它此去时，早攀月桂枝。","金冠霞帔，有分妆束你。","我称孺人，。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2595","tags":[]},{"id":"poem-fb15f27aff33f2f25912359e","title":"江陵府初试澄心如水","author":"卢肇","dynasty":"唐","verses":["丹心何所喻，唯水并清虚。","莫测千寻底，难知一勺初。","内明非有物，上善本无鱼。","澹泊随高下，波澜逐卷舒。","养蒙方浩浩，出险每徐徐。","若灌情田里，常流尽不如。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-abd4140e-ba4f-45ee-85e7-20059eee6bd3","tags":[]},{"id":"poem-fb16688713a61a3010a273b3","title":"谢盘野黄文昌  其二","author":"释居简","dynasty":"宋","verses":["日课芳菲谱，归来手自栽。","有诗随意好，无日不花开。","鸥鹭论心事，云山入酒杯。","绮罗帘幕静，处处小蓬莱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-2b3fc4b5-f4b7-4355-8799-826da1544321","tags":[]},{"id":"poem-fb25522ac6d7501327bb31de","title":"七夕宴悬圃二首 二","author":"高宗皇帝","dynasty":"唐","verses":["霓裳转云路，凤驾俨天潢。","亏星凋夜靥，残月落朝璜。","促欢今夕促，长离别后长。","轻梭聊驻织，掩泪独悲伤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-792e7017-3954-4a3b-a167-e183f17ca707","tags":[]},{"id":"poem-fb257d0a9caf81c9d506604e","title":"横吹曲辞 陇头水","author":"罗隐","dynasty":"唐","verses":["借问陇头水，年年恨何事。","全疑呜咽声，中有征人泪。","自古无长策，况我非深智。","何计谢潺湲，一宵空不寐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ca2d41ce-a190-4d9b-b000-1670b6ffc9f6","tags":[]},{"id":"poem-fb310098313436dfd824a076","title":"浪淘沙·璧月挂秋宵","author":"高登","dynasty":"宋","verses":["璧月挂秋宵。","丹桂香飘。","广寒宫殿路迢迢。","试问嫦娥缘底事，欲下层霄。","兰玉自垂髫。","拜命当朝。","神仙会里且逍遥。","分取壶中闲日月，来伴王乔。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-237","tags":[]},{"id":"poem-fb3331291c6984b76bd2d154","title":"蜀葵","author":"王镃","dynasty":"宋","verses":["片片川罗湿露凉，染红才了染鹅黄。","花根疑是忠臣骨，开出倾心向太阳。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-1cdc32c0-a92f-44ac-a9dd-ec0def31f492","tags":[]},{"id":"poem-fb35d06f58710b2357f5dc3d","title":"杜少府之任蜀州","author":"王勃","dynasty":"唐","verses":["城阙辅三秦，风烟望五津。","与君离别意，同是宦游人。","海内存知己，天涯若比邻。","无为在歧路，儿女共沾巾。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-杜少府之任蜀州","tags":[]},{"id":"poem-fb38a37795a258e4947aef80","title":"单父逢邓司仓覆仓库因而有赠","author":"高适","dynasty":"唐","verses":["邦牧今坐啸，群贤趋纪纲。","四人忽不扰，耕者遥相望。","粲粲府中妙，授词如履霜。","炎炎伏热时，草木无晶光。","匹马度睢水，清风何激扬。","校缗阅帑藏，发廪欣斯箱。","邂逅得相逢，欢言至夕阳。","开襟自公余，载酒登琴堂。","举桮挹山川，寓目穷毫芒。","白鸟向田尽，青蝉归路长。","醉中不惜别，况乃正游梁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cfec06fe-678e-45b9-8da3-93ed36cb9f9e","tags":[]},{"id":"poem-fb3cbaa8036f9f0eb62f4f79","title":"·","author":"骆仲舒","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-dfabd999-693c-47a5-8941-f9691b81fc7d","tags":[]},{"id":"poem-fb41274da03262c282361257","title":"秋日美晴郡楼闲眺寄荆南张书记","author":"李德裕","dynasty":"唐","verses":["高槛凉风起，清川旭景开。","秋声向野去，爽气自山来。","霄外鸿初返，簷间燕已归。","不因烟雨夕，何处梦阳台。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-a3af5d50-130f-4e9d-89ef-4538f1ac3fce","tags":[]},{"id":"poem-fb46fe4798a6b0586c844d97","title":"陪郑王相公赋簷前垂冰应教依韵","author":"徐铉","dynasty":"宋","verses":["窗外虚明雪乍晴，簷前垂霤尽成冰。","长廊瓦叠行行密，晚院风高寸寸增。","玉指乍拈簪尚愧，金阶时坠磬难胜。","晨餐堪醒曹参酒，自恨空肠病不能。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-862bb5ef-1239-493a-bcad-2c667c5fd933","tags":[]},{"id":"poem-fb4d60cdfe3e0b24a20b94f5","title":"菩萨蛮·绿芜墙绕青苔院","author":"陈克","dynasty":"宋","verses":["绿芜墙绕青苔院。","中庭日淡芭蕉卷。","蝴蝶上阶飞。","烘帘自在垂。","玉钩双语燕。","宝甃杨花转。","几处簸钱声。","绿窗春睡轻。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-271","tags":["宋词三百首"]},{"id":"poem-fb59fe59ebebae03ff4e2479","title":"庐山谣寄卢侍御虚舟","author":"李白","dynasty":"唐","verses":["我本楚狂人，凤歌笑孔丘。","手持绿玉杖，朝别黄鹤楼。","五岳寻仙不辞远，一生好入名山游。","庐山秀出南斗傍，屏风九叠云锦张，影落明湖青黛光。","金阙前开二峰长，银河倒挂三石梁。","香炉瀑布遥相望，回厓沓嶂凌苍苍。","翠影红霞映朝日，鸟飞不到吴天长。","登高壮观天地间，大江茫茫去不还。","黄云万里动风色，白波九道流雪山。","好为庐山谣，兴因庐山发。","闲窥石镜清我心，谢公行处苍苔没。","早服还丹无世情，琴心三叠道初成。","遥见仙人彩云里，手把芙蓉朝玉京。","先期汗漫九垓上，愿接卢敖游太清。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4e491c2f-c3c8-487f-8e76-63bd0a811b30","tags":["唐诗三百首","庐山","黄鹤楼","写景","归隐","七言古诗","山水"]},{"id":"poem-fb6ed266bc7d72f5646eec78","title":"逢江客问南中故人因以诗寄","author":"司空曙","dynasty":"唐","verses":["南客何时去，相逢问故人。","望乡空泪落，嗜酒转家贫。","疎嬾辞微禄，东西任老身。","上楼多看月，临水共伤春。","五柳终期隐，双鸥自可亲。","应怜折腰吏，冉冉在风尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-58fe608e-8583-4be2-951a-4303ebac66f3","tags":[]},{"id":"poem-fb70558541f0cee445f9f434","title":"夜泊牛渚怀古","author":"李白","dynasty":"唐","verses":["牛渚西江夜，青天无片云。","登舟望秋月，空忆谢将军。","余亦能高咏，斯人不可闻。","明朝挂帆席，枫叶落纷纷。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7e1be9c9-fa2f-44c2-a6bc-3edcece745fe","tags":["唐诗三百首","怀古","五言律诗","月亮"]},{"id":"poem-fb71057cac22322adb20bc99","title":"水龙吟·问春何苦匆匆","author":"晁补之","dynasty":"宋","verses":["问春何苦匆匆，带风伴雨如驰骤。","幽葩细萼，小园低槛，壅培未就。","吹尽繁红，占春长久，不如垂柳。","算春常不老，人愁春老，愁只是、人间有。","春恨十常八九。","忍轻辜、芳醪经口。","那知自是，桃花结子，不因春瘦。","世上功名，老来风味，春归时候。","纵樽前痛饮，狂歌似旧，情难依旧。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-220","tags":["宋词三百首"]},{"id":"poem-fb713e9b04a375155ce1a06d","title":"乌夜啼·昨夜风兼雨","author":"李煜","dynasty":"五代","verses":["昨夜风兼雨，帘帏飒飒秋声。","烛残漏断频攲枕，起坐不能平。","世事漫随流水，算来一梦浮生。","醉乡路稳宜频到，此外不堪行。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-5","tags":[]},{"id":"poem-fb785f1aa57757143f2739a8","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［末］恩东免嗟吁，且听覆。","言清行浊心贪污，违法度，恩和义，都不顾。","半载夫妻曾厮聚，一时间却把婵娟误。","［合前］。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8191","tags":[]},{"id":"poem-fb8c9e31a80436fac01e51b2","title":"猛士行","author":"李廓","dynasty":"唐","verses":["战鼓惊沙恶天色，猛士虬髯眼前黑。","单于衣锦日行兵，阵头走马生擒得。","幽幷少年不敢轻，虎狼窟里空手行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-8265398b-e695-416b-8449-4d3d1a862a10","tags":[]},{"id":"poem-fb9acd2acaebe63a199fa007","title":"洛阳城外别皇甫湜","author":"李贺","dynasty":"唐","verses":["洛阳吹别风，龙门起断烟。","冬树束生涩，晚紫凝华天。","单身野霜上，疲马飞蓬间。","凭轩一双泪，奉坠绿衣前。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-c8711b9e-4367-419b-8a7d-83e4f8ee8a98","tags":[]},{"id":"poem-fba887813763ad6a5401d4cd","title":"送蔡山人","author":"高适","dynasty":"唐","verses":["东山布衣明古今，自言独未逢知音。","识者阅见一生事，到处豁然千里心。","看书学劒长辛苦，近日方思谒明主。","斗酒相留醉复醒，悲歌数年泪如雨。","丈夫遭遇不可知，买臣主父皆如斯。","我今蹭蹬无所似，看尔崩腾何若为。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9a09444a-363a-4ca9-9537-2c6a91683de4","tags":[]},{"id":"poem-fbaf6bf268be0f763fd35b3a","title":"郊庙歌辞 梁郊祀乐章 庆和 三","author":"赵光逢、张衮","dynasty":"唐","verses":["开九门，怀百神。","通肸蚃，接氤氲。","明粢荐，广乐陈。","奠嘉璧，燎芳薪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-c83d6fd3-b533-4f81-8274-cfc77d39ce77","tags":[]},{"id":"poem-fbafaa9dec163b1afbd51584","title":"清明","author":"王禹偁","dynasty":"宋","verses":["无花无酒过清明，兴味萧然似野僧。","昨日邻家乞新火，晓窗分与读书灯。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-清明","tags":[]},{"id":"poem-fbb4c7e37e952acce3a84330","title":"山行经樵翁","author":"鲍溶","dynasty":"唐","verses":["我心劳我身，远道谁与论。","心如木中火，忧至常自燔。","披访结恩地，世人轻报恩。","女无良媒识，知入何人门。","寒日行深山，路由谷中村。","田翁樵采熟，男女讴吟喧。","借问身命谋，上言媿乾坤。","时清公赋薄，力勤地利繁。","下念草木年，坐家见重孙。","举案馈宾客，糟浆盈陶尊。","醉闲鹿裘煗，白发舞轩轩。","仰羡太古人，余将破行辕。","遑遑问身事，师友难为言。","离歌又行去，落日低寒泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cca3e969-8205-47ac-baf8-9bf7c29bf0f6","tags":[]},{"id":"poem-fbb9b2a1986d930626de5fc5","title":"华景洞","author":"吕愿中","dynasty":"宋","verses":["斯洞名华景，累累乳石悬。","虚崖疑月窟，绝顶瞰江湍。","岩底金仙寺，峰头玉井莲。","地形居众外，气象伟无前。","徙杖观初日，归舆触暝烟。","蔽林排翠幄，封径簇花钿。","爽致资清赏，镌题记昔年。","猿啼声应谷，云破月侵筵。","策蹇追华驷，鸣髇指坠鸢。","谁人能画此，为倩老龙眠。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-5ace7e03-ac51-4d5e-8989-40a6f69df2b0","tags":[]},{"id":"poem-fbba4cc9ec5881b1614b4fbd","title":"绛都春引","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生上)年乖运蹇，枉有冲天气宇。","最苦堂堂七尺躯，受无限嗟吁，似饿虎岩前睡也，困龙失却明珠。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8792","tags":[]},{"id":"poem-fbbcc939b404aa89c86ed8f7","title":"酬程延秋夜即事见赠","author":"韩翃","dynasty":"唐","verses":["长簟迎风早，空城澹月华。","星河秋一雁，砧杵夜千家。","节候看应晚，心期卧亦赊。","向来吟秀句，不觉已鸣鸦。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ce493923-7c4b-41a9-94e9-cf95741c018c","tags":["唐诗三百首","写景","酬答","五言律诗"]},{"id":"poem-fbd040b76d08aaf5caf46b88","title":"山阳即席献裴中丞","author":"赵嘏","dynasty":"唐","verses":["早年天上见清尘，今日楼中醉一春。","暂肯剖符临水石，几曾焚笔动星辰。","琼台雪映迢迢鹤，蓬岛波横浩浩津。","好是仙家羽衣使，欲教垂涕问何人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-008ee9a3-bded-4277-b1fb-abed94d1c941","tags":[]},{"id":"poem-fbd9b9cbeb080cd9aaab2c44","title":"马蹄痕","author":"吕从庆","dynasty":"唐","verses":["一泓流水旧多情，拂尘乘骢跃浅萍。","父老竞传遗迹在，不知仙客是何名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-385b2d6f-c793-41ff-9393-660b039af9c0","tags":[]},{"id":"poem-fbe0d50516ee50a7af8b4286","title":"止酒","author":"张栻","dynasty":"宋","verses":["渊明通达士，止酒乃成诗。","终焉未能忘，寄意良在兹。","勇哉典午君，覆觞无再期。","念彼万乘贵，艰难有深思。","况乃一介士，而或志可移。","祓斋揆前训，刚制圣所辞。","铭心谅无斁，多言亦奚为。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-d20ec042-bc0b-462f-bb41-9f76796caa0e","tags":[]},{"id":"poem-fbe260ed67622923e24e0c37","title":"宫词  其一九","author":"张公庠","dynasty":"宋","verses":["御柳丝长挂玉栏，不须惆怅百花残。","还知三月春虽晚，好从金舆看牡丹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-067e0225-b4dd-4b08-b27d-8f794d61ccd7","tags":[]},{"id":"poem-fbe9a864c926676308cdde62","title":"高僧石","author":"陈岩","dynasty":"宋","verses":["柏根翻动一炉香，白足高僧礼梵王。","还了十方行脚债，却来山顶放圆光。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-a47090ea-7b42-439f-b9e2-9af09c001804","tags":[]},{"id":"poem-fbfd01ea15996b9fc7d5c6b1","title":"九怀·昭世","author":"王褒","dynasty":"汉","verses":["世溷兮冥昏，违君兮归真。","乘龙兮偃蹇，高回翔兮上臻。","袭英衣兮缇[纟习]，披华裳兮芳芬。","登羊角兮扶舆，浮云漠兮自娱。","握神精兮雍容，与神人兮相胥。","流星坠兮成雨，进瞵盼兮上丘墟。","览旧邦兮滃郁，余安能兮久居。","志怀逝兮心懰栗，纡余辔兮踌躇。","闻素女兮微歌，听王后兮吹竽。","魂凄怆兮感哀，肠回回兮盘纡。","抚余佩兮缤纷，高太息兮自怜。","使祝融兮先行，令昭明兮开门。","驰六蛟兮上征，竦余驾兮入冥。","历九州兮索合，谁可与兮终生。","忽反顾兮西囿，睹轸丘兮崎倾。","横垂涕兮泫流，悲余后兮失灵。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-41","tags":[]},{"id":"poem-fc01f0059ca6cbce30ef3119","title":"西河·佳丽地","author":"周邦彦","dynasty":"宋","verses":["佳丽地。","南朝盛事谁记。","山围故国绕清江，髻鬟对起。","怒涛寂寞打孤城，风樯遥度天际。","断崖树，犹倒倚。","莫愁艇子曾系。","空馀旧迹郁苍苍，雾沈半垒。","夜深月过女墙来，赏心东望淮水。","酒旗戏鼓甚处市。","想依稀、王谢邻里。","燕子不知何世。","入寻常、巷陌人家，相对如说兴亡，斜阳里。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-238","tags":["宋词三百首"]},{"id":"poem-fc054d030ff5075b325c1bff","title":"落花","author":"李咸用","dynasty":"唐","verses":["拾得移时看，重思造化功。","如何飘丽景，不似遇春风。","满地余香在，繁枝一夜空。","秪应公子见，先忆坠楼红。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-5cef109e-90f7-4734-924f-f81e826a52a6","tags":[]},{"id":"poem-fc0bd47e87a139c929e44ec9","title":"题十三弟竹园","author":"刘言史","dynasty":"唐","verses":["绕屋扶疎耸翠茎，苔滋粉漾有幽情。","丹阳万户春光静，独自君家秋雨声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ab5d3922-f997-44f7-8cc7-72b017e320f8","tags":[]},{"id":"poem-fc0c8178aa9d57d37e359d7f","title":"相和歌辞 玉阶怨","author":"李白","dynasty":"唐","verses":["玉阶生白露，夜久侵罗袜。","却下水精帘，玲珑望秋月。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f93545e7-747e-4d12-a6c8-e484c46b2860","tags":["唐诗三百首","孤独","宫怨","乐府"]},{"id":"poem-fc0d07de5b2cbade5a3a27b4","title":"菩萨蛮·玉钗风动春幡急","author":"牛峤","dynasty":"五代","verses":["玉钗风动春幡急，交枝红杏笼烟泣。","楼上望卿卿，窗寒新雨晴。","熏炉蒙翠被，绣帐鸳鸯睡。","何处有相知，羡他初画眉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-16","tags":[]},{"id":"poem-fc0dc2c1557773a2264191af","title":"秋夜寄丘二十二员外","author":"韦应物","dynasty":"唐","verses":["怀君属秋夜，散步咏凉天。","山空松子落，幽人应未眠。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-96455db1-a0c6-402c-8892-05c6b9a3d029","tags":["唐诗三百首","秋天","怀人","五言绝句"]},{"id":"poem-fc17f00efcd29535febff58f","title":"送从叔阳冰祇召赴都","author":"李嘉祐","dynasty":"唐","verses":["自小从游惯，多由戏笑偏。","常时矜礼数，渐老荷优怜。","见主承休命，为郎贵晚年。","伯喈文与篆，虚作汉家贤。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-528dac78-a720-4031-8164-12f0f165c2e1","tags":[]},{"id":"poem-fc1b00f01bd14a23b5c401b7","title":"浣溪沙·分付心情作上元","author":"韩淲","dynasty":"宋","verses":["分付心情作上元。","不知投老在林泉。","谁将村酒劝觥船。","月影静摇风柳外，霜华寒浸雪梅边。","醉敧乌帽忽醒然。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-475","tags":[]},{"id":"poem-fc1c88b52cd017e0b4641348","title":"小游仙诗九十八首 九十二","author":"曹唐","dynasty":"唐","verses":["北斗西风吹白榆，穆公相笑夜投壶。","花前玉女来相问，赌得青龙许赎无。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-93715a3c-0494-4fde-9cbe-f62af5ee8f76","tags":[]},{"id":"poem-fc20a218e2a26deb30c526d0","title":"贺鹤林吴尚书赴召除隆兴","author":"宋伯仁","dynasty":"宋","verses":["鸾翔芝检下溪堂，醉梦惊回午正凉。","宠报帝俞催宰相，且将州绂召文昌。","苹花襟袖宫花近，诗草帘栊谏草香。","大化一新多吉士，卷阿历历告成王。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-06b017a1-a926-41fd-a0a5-ca253d8bb08e","tags":[]},{"id":"poem-fc31e90cc9bef0a9f6efd52b","title":"杏花","author":"司空图","dynasty":"唐","verses":["诗家偏为此伤情，品韵由来莫与争。","解笑亦应兼解语，只应慵语倩莺声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c8fd429d-5cdf-4bda-9d0f-e04f12f224af","tags":[]},{"id":"poem-fc3e9cd2b24df541e1f5bd80","title":"小桃红","author":"刘唐卿《白兔记》","dynasty":"元","verses":["腊天不雨，喜在庄农，爱日暄晴昼也。","转过疏篱步跷踵，极目看西东，四下里影无踪，只听得雷声也。","莫不是老倒无能？怨天公令自行冬。","远远望见卧牛岗边，一道火光，透入天门。","莫非小的失火？待我观看。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8826","tags":[]},{"id":"poem-fc4a0fabcce1030164b567bd","title":"题李长啸漕元赁居","author":"宋伯仁","dynasty":"宋","verses":["可种梅花便可居，此身安处即吾庐。","胸中丘壑无今古，笔底烟霞自卷舒。","著脚且坚君子操，知心自有圣人书。","吾侪幸是苕川客，只好溪头学钓鱼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b7578253-b795-4ee7-aefa-dd860f946baa","tags":[]},{"id":"poem-fc6384e49e2cd74fad1cf38e","title":"李郎中林亭","author":"曹松","dynasty":"唐","verses":["秪向砌边流野水，樽前上下看鱼儿。","笋蹊已长过人竹，藤径从添拂面丝。","若许白猿垂近户，即无红果压低枝。","大才必拟逍遥去，更遣何人佐盛时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-11fe4bfb-12c3-49ff-be32-c2d0c0eb526d","tags":[]},{"id":"poem-fc7522dd375ca3cb4f9cbbfe","title":"浣溪沙","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["千里莺啼绿映红，(丑白)水村山郭酒旗风，(净白)行人如在画图中。","(末白)不暖不寒天气好，或来或往旅人逢，(合)此时谁不叹西东。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4970","tags":[]},{"id":"poem-fc8705ff1da9876481cd842b","title":"临海太守惠予赤城石报以是诗","author":"李德裕","dynasty":"唐","verses":["闻君采奇石，剪断赤城霞。","潭上倒虹影，波中摇日华。","仙岩接绛气，谿路杂桃花。","若值客星去，便应随海槎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-c376716e-14a2-4ef3-99eb-f6ab69daff67","tags":[]},{"id":"poem-fc886edb002e998201b84d9e","title":"·","author":"李煜","dynasty":"五代","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-b20c802c-41b2-423e-a538-3bdea1525f72","tags":[]},{"id":"poem-fc95c755a3cbce333eb11fbf","title":"华顶道者","author":"项斯","dynasty":"唐","verses":["仙人掌中住，生有上天期。","已废烧丹处，犹多种杏时。","养龙于浅水，寄鹤在高枝。","得道复无事，相逢尽日棋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-507228b0-2eb8-475a-afa7-5bbc1dbcda4b","tags":[]},{"id":"poem-fc9b98061fc82c3e7455b543","title":"题周谏别业","author":"皎然","dynasty":"唐","verses":["隐身苕上欲如何，不著青袍爱绿萝。","柳巷任疎容马入，水篱从破许船过。","昂藏独鹤闲心远，寂历秋花野意多。","若访禅斋遥可见，竹窗书幌共烟波。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-0b222621-d127-4df5-b8a9-c1499378aa19","tags":[]},{"id":"poem-fc9d037fca0e324c37337027","title":"和厉玄侍御题户部相公庐山草堂","author":"刘得仁","dynasty":"唐","verses":["白云居创毕，诏入凤池年。","林长双峰树，潭分并寺泉。","石溪盘鹤外，岳室闭猨前。","柱史题诗后，松前更肃然。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9c71caa8-2dec-4fc9-abdb-1adcf745f1f4","tags":["庐山"]},{"id":"poem-fc9d9c62212557f21a72a640","title":"送林府教英发","author":"释居简","dynasty":"宋","verses":["元化钧陶铸，先生独铸颜。","不祥麾跃冶，至蕴剖藏山。","幌冷云垂地，名修玉缀班。","圜桥俨冠带，鹄立望公还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-45b035cc-4662-4fae-93a9-837df4038689","tags":[]},{"id":"poem-fca4942c7e55fea35b76d3b6","title":"诗品二十四则 旷达","author":"司空图","dynasty":"唐","verses":["生者百岁，相去几何。","欢乐苦短，忧愁实多。","何如尊酒，日往烟萝。","花覆茆簷，疎雨相过。","倒酒既尽，杖藜行过。","孰不有古，南山峨峨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2c9e4874-a933-4ae0-ac01-4c0bfc39d6c5","tags":[]},{"id":"poem-fcaf730055dcae4ad4d2fd2b","title":"偈颂（幷序○序为南岳齐己撰） 七十五","author":"居遁","dynasty":"唐","verses":["老似临江树，风摇枝必危。","岸崩随水去，入海勿人追。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f133a646-7a7d-4eda-89f1-6571eeffb958","tags":["衡山"]},{"id":"poem-fcb378969002d5997434a4b8","title":"咏史诗 李陵台","author":"胡曾","dynasty":"唐","verses":["北入单于万里疆，五千兵败滞穷荒。","英雄不伏蛮夷死，更筑高台望故乡。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ff0bff12-da29-4555-ab92-725cf9f22420","tags":[]},{"id":"poem-fcb4c23c13555df78e7ec3b7","title":"雨","author":"徐夤","dynasty":"唐","verses":["引电随龙密又轻，酒桮闲噀得嘉名。","千山草木如云暗，陆地波澜接海平。","洒竹几添春睡重，滴簷偏遣夜愁生。","阴妖冷孽成何怪，敢蔽高天日月明。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a638f6e8-ba9f-48fa-ba33-e23c8e4d71b2","tags":[]},{"id":"poem-fcbb6397f8f813376b639c9a","title":"又一首","author":"张𬸦","dynasty":"唐","verses":["自隐风流到，人前法用多。","计时应拒得，佯作不禁他。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-04d1c3e6-c831-4f2d-b983-a8d77c34b794","tags":[]},{"id":"poem-fcbda3784c4173c9dca96749","title":"卜算子·梦里不知眠","author":"陈瓘","dynasty":"宋","verses":["梦里不知眠，觉后眠何在。","试问眠身与梦身，那个能祗对。","醉后有人醒，醒了无人醉。","要识三千与大千，不在微尘外。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-551","tags":[]},{"id":"poem-fcbdfae95a1463fef0621a0b","title":"送陆处士","author":"张乔","dynasty":"唐","verses":["樽前放浩歌，便起泛烟波。","舟楫故人少，江湖明月多。","孤峰经宿上，僻寺共云过。","若向仙岩住，还应著薜萝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-9b653a15-b561-4f8f-903d-33bc4b33234f","tags":[]},{"id":"poem-fcbe71d08e1b15adc96090ec","title":"虞美人·飞梁石径关山路","author":"蔡伸","dynasty":"宋","verses":["飞梁石径关山路。","惨淡秋容暮。","一行新雁破寒空。","肠断碧云千里、水溶溶。","鸾衾欲展谁堪共。","帘幕霜华重。","鸭炉香尽锦屏中。","幽梦今宵何许、与君同。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-960","tags":[]},{"id":"poem-fcc311fe86f20ef40d3ac7c1","title":"奉赠苗员外","author":"李端","dynasty":"唐","verses":["朱户敞高扉，青槐碍落晖。","八龙承庆重，三虎递朝归。","坐竹人声绝，横琴鸟语稀。","花慙潘岳貌，年称老莱衣。","叶暗新樱熟，丝长粉蝶飞。","应怜鲁儒贱，空与故山违。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-0229d4a7-2410-41e2-ab77-0022f9a70c38","tags":[]},{"id":"poem-fcc67093fa7c4761858b7eba","title":"南歌子·惹恨还添恨","author":"毛熙震","dynasty":"五代","verses":["惹恨还添恨，牵肠即断肠。","凝情不语一枝芳，独映画帘闲立，绣衣香。","暗想为云女，应怜傅粉郎。","晚来轻步出闺房，髻慢钗横无力，纵猖狂。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-48","tags":[]},{"id":"poem-fccadbbb376a7c0842f23d48","title":"忆朝阳峰前居","author":"项斯","dynasty":"唐","verses":["每忆闲眠处，朝阳最上峰。","溪僧来自远，林路出无踪。","败褐黏苔徧，新题出石重。","霞光侵曙发，岚翠近秋浓。","健羡机能破，安危道不逢。","雪残猨到阁，庭午鹤离松。","此地虚为别，人间久未容。","何时无一事，却去养疎慵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-bd11ab77-cdc3-45f4-9cf9-767ea00098d3","tags":[]},{"id":"poem-fcd57f1a2b6b399cfe66ef68","title":"浆水令","author":"无名氏《张协状元》","dynasty":"元","verses":["告莫说张状元，才说后泪涟涟。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2732","tags":[]},{"id":"poem-fcd6735bcc49cba90e3f14d2","title":"漫塘名陈内机小斋曰能止","author":"释居简","dynasty":"宋","verses":["莫闚殽与函，峭绝青错磨。","可无济胜具，振衣披峩峩。","更复游吕梁，虎眼漩作涡。","堂堂济深涉，如此忠信何。","游子听我语，审听毋媕婀。","通都横九逵，平平非仄颇。","并驾方峥嵘，辐辏相骈罗。","嗜进弗知了，十步九跌蹉。","何如反吾辕，自少不自多。","怡然事天全，盎然毓天和。","倦翼安故林，归云仍中阿。","晓猿时自吟，好鸟时自歌。","凉树坐茂密，醉石眠坡陁。","何须鹑奔奔，静胜超凡科。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9a7a0ac9-0585-458e-951e-921f511344cc","tags":[]},{"id":"poem-fcdef7dc5bff1bd9ed0b18ee","title":"啄木儿","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["苦！我亲衰老，妻幼娇，万里关山音信杳。","他那里举目凄凄，我这里回首迢迢。","他那里望得眼穿儿不到，俺这里哭得泪干亲难保。","闪杀人么一封丹凤诏。","(黄门唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5032","tags":[]},{"id":"poem-fce1f8c5319d92f28d158f3c","title":"将去广陵别史员外南斋","author":"徐铉","dynasty":"宋","verses":["家声曾与金张辈，官署去居何宋间。","起得高斋临静曲，种成奇树学他山。","鸳鸾终日同醒醉，萝薜常时共往还。","贱子今朝独南去，不堪回首望清闲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-214524cb-abae-4830-b5ab-0d12e7e0fc9d","tags":[]},{"id":"poem-fce7ac6404ec3eab81e020ec","title":"董逃行","author":"张籍","dynasty":"唐","verses":["洛阳城头火曈曈，乱兵烧我天子宫。","宫城南面有深山，尽将老幼藏其间。","重岩为屋橡为食，丁男夜行候消息。","闻道官军犹掠人，旧里如今归未得。","董逃行，汉家几时重太平。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-593f42d7-3b06-4409-bd98-00513a326392","tags":[]},{"id":"poem-fcf6708296a255fc528d087e","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["五百位官员，何可向前？又何苦特骨底，要嫁状元？(丑)伊着我，此心坚。","石头须，定教它穿。","(合同前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2626","tags":[]},{"id":"poem-fd105110ef0f294f13a60398","title":"山中","author":"李咸用","dynasty":"唐","verses":["一簇烟霞荣辱外，秋山留得傍簷楹。","朝钟暮鼓不到耳，明月孤云长挂情。","世上路岐何缭绕，水边蓑笠称平生。","寻思阮籍当时意，岂是途穷泣利名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-cc190344-6143-4e56-ada7-38a2fa786587","tags":[]},{"id":"poem-fd1ce67b72c3745c1ea80db6","title":"凉州词二首 一","author":"王之涣","dynasty":"唐","verses":["黄河远上白云间，一片孤城万仞山。","羌笛何须怨杨柳，春光不度玉门关。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-526d4ecc-e123-4b9d-a213-958bb947593d","tags":["唐诗三百首","黄河","山水","写景","乐府","思乡","边塞","将士"]},{"id":"poem-fd259b49720fbe6f469f0141","title":"同舍弟佶班韦二员外秋苔对之成咏","author":"包何","dynasty":"唐","verses":["每看苔藓色，如向簿书闲。","幽思缠芳树，高情寄远山。","雨痕连地绿，日色出林斑。","却笑兴公赋，临危滑石间。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c2897a95-99ad-4753-a6f2-2136d02d696e","tags":[]},{"id":"poem-fd32c1332ab799acf3300cf2","title":"读陶诗  其一","author":"赵崇嶓","dynasty":"宋","verses":["端居洗尘虑，细读渊明诗。","畴昔慕此翁，寤寐忘调饥。","此翁非诗人，而有天然姿。","纷纷世事中，采采黄菊枝。","此语人共赏，此意畴复知。","知即翁之徒，高风接皇羲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-7e253c8f-2ff7-4d02-a952-a2c24df98def","tags":[]},{"id":"poem-fd3538bcb31b972cefd78075","title":"塞外三首 二","author":"郑愔","dynasty":"唐","verses":["荒垒三秋夕，穷郊万里平。","海阴凝独树，日气下连营。","戎斾霜旋重，边裘夜更轻。","将军犹转战，都尉不成名。","折柳悲春曲，吹笳断夜声。","明年汉使返，须筑受降城。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-42964d1f-7861-457b-8a4c-ddb01c8e4161","tags":[]},{"id":"poem-fd3c9c5033def066f4dc0d88","title":"采桑子·楚山削玉云中碧","author":"谢逸","dynasty":"宋","verses":["楚山削玉云中碧，影落沙汀。","秋水澄凝。","一抹江天雁字横。","金钱满地西风急，红蓼烟轻。","帘外砧声。","惊起青楼梦不成。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-599","tags":[]},{"id":"poem-fd423aaf04e2caa7cc493533","title":"咏木槿树题武进文明府厅","author":"刘庭琦","dynasty":"唐","verses":["物情良可见，人事不胜悲。","莫恃朝荣好，君看暮落时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-476908f1-15ce-4d83-a8b8-178a866d9f39","tags":["咏物诗","咏物"]},{"id":"poem-fd44ae712424ecf20e1d9840","title":"读远书","author":"徐凝","dynasty":"唐","verses":["两转三回读远书，画簷愁见燕归初。","百花时节教人懒，云髻朝来不欲梳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-eecab1ae-38c6-4ea2-83da-9c5612bd7d2b","tags":[]},{"id":"poem-fd50c46190cd9077333ee47d","title":"寄焦公泽","author":"华镇","dynasty":"宋","verses":["身世旋蓬转，年华激矢忙。","漂流轻楚越，契阔易参商。","窃预三千日，行几二十霜。","金声留逸响，玉润有余光。","仕路虽叨践，心蹊未敢荒。","轩昂遗俗物，感激企前芳。","燕雀惊鸿鹄，鸱鸢吓凤凰。","倾都无孟子，通国毁匡章。","曾席虽云远，韩门未见忘。","铄金频减价，投杼几循墙。","素履微难任，流言众觉强。","箴言曾展转，攻鼓或相将。","睠想周宾裔，来居禹计乡。","一门如旅燕，三世寄飞梁。","何地逢遗秉，谁垣有树桑。","釜鱼时肖范，储石每矜扬。","儒术资斑见，乡评假寸长。","芹藜经伏腊，苹藻备烝尝。","纻絮亏冬褐，丹铅薄晓妆。","晚蝉无重翼，瀌雪有骄阳。","唐彀虚曾入，齐飞宛未翔。","十年劳俛仰，三釜足凄凉。","怀刺终思重，车尘旧耻望。","有惭猗顿富，徒效老莱装。","曲表求端影，奔车倚怒螳。","力微甘黾勉，道拙分摧藏。","好恶乡人僻，风波世路常。","棘薪今合重，瓜蔓昔还伤。","颊舌知无补，丝桐或可量。","未教轻割席，庶复许升堂。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-fe09e5c0-02fc-4836-839b-33408a905c30","tags":[]},{"id":"poem-fd5339f67cb72b49272a0fc2","title":"梅花引·千里月","author":"刘均国","dynasty":"宋","verses":["千里月，千山雪。","梅花正落寒时节。","一枝昂。","一枝藏。","清香冷艳、天赋与孤光。","孤光似被珠帘隔。","风度烟遮好颜色。","粉垂垂。","玉累累。","先春挺秀，不管百花知。","似霜结。","与霜别。","莫使幽人容易折。","短墙边。","矮窗前。","横斜峭影，重叠斗婵娟。","黄昏惯听楼头角。","只恐听时零乱落。","醉来看。","醒来看。","萦绊丽人，潇洒倚阑干。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-864","tags":[]},{"id":"poem-fd69431d277cf2c303d742a5","title":"宋中十首 二","author":"高适","dynasty":"唐","verses":["朝临孟诸上，忽见芒砀间。","赤帝终已矣，白云长不还。","时清更何有，禾黍徧空山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-1082dfa9-28dd-4dfe-9e5e-e8baa0bea8ad","tags":[]},{"id":"poem-fd6ba924b7ea98d29dffa175","title":"霜天晓角","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["难挨怎避，灾祸重重至？最苦婆婆死矣，公公病，又将危。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5099","tags":[]},{"id":"poem-fd6e2a58c7871a0f72e155bc","title":"友人亭松","author":"于邺","dynasty":"唐","verses":["俛仰不能去，如逢旧友同。","曾因春雪散，见在华山中。","何处有明月，访君听远风。","相将归未得，各占石岩东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-183ffb29-cb99-4eb4-b349-db564ff8bd07","tags":[]},{"id":"poem-fd712bd9c58681bac9de31cb","title":"铜雀妓","author":"高适","dynasty":"唐","verses":["日暮铜雀迥，秋深玉座清。","萧森松柏望，委郁绮罗情。","君恩不再得，妾舞为谁轻。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-66fd0cb9-5f5b-4299-b7bd-a2d03ca5c89e","tags":[]},{"id":"poem-fd71447d7add19059d4e3cda","title":"寄终南真空禅师","author":"马戴","dynasty":"唐","verses":["闲想白云外，了然清净僧。","松门山半寺，夜雨佛前灯。","此境可长住，浮生自不能。","一从林下别，瀑布几成冰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-3a4f111b-6ab4-4457-9021-8c216f44ddf7","tags":[]},{"id":"poem-fd74d9650f3c153a1160f55f","title":"郊庙歌辞 享惠昭太子庙乐章 送神","author":"王涯","dynasty":"唐","verses":["威仪毕陈，备乐将阕。","苞茅酒缩，膋萧香彻。","宫臣展事，肃雍在列。","迎精送往，厥鉴昭晰。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5d132fee-78bd-4ca6-9f30-ebe3c81c95f7","tags":[]},{"id":"poem-fd80a51b687c0c4c71fa7707","title":"新柳","author":"司空曙","dynasty":"唐","verses":["全欺芳蕙晚，似妬寒梅疾。","撩乱发青条，春风来几日。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-35577519-453b-4de0-a631-080f9f90eca2","tags":["柳树"]},{"id":"poem-fd81986add05fe7fa0ccff2d","title":"下第出春明门","author":"李山甫","dynasty":"唐","verses":["曾和秋雨驱愁入，却向春风领恨回。","深谢灞陵堤畔柳，与人头上拂尘埃。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-1e079c98-2067-4dd7-9665-8b84fdc7a7ad","tags":[]},{"id":"poem-fd88bc741047aae777b1c31d","title":"客舍有怀因呈诸在事","author":"崔峒","dynasty":"唐","verses":["读书常苦节，待诏岂辞贫。","暮雪犹驱马，晡飡又寄人。","愁来占吉梦，老去惜良辰。","延首平津阁，家山日已春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-6b12c992-250e-4231-9b19-8fada6c0f668","tags":[]},{"id":"poem-fd8a01e0fb5bc04716137f4c","title":"独住僧","author":"徐凝","dynasty":"唐","verses":["百补袈裟一比丘，数茎长睫覆青眸。","多应独住山林惯，唯照寒泉自剃头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4873d783-4757-4029-85c0-69dc29106ed5","tags":[]},{"id":"poem-fd908f803ed964fa0ef933aa","title":"谢秀才有妾缟练改从于人秀才留之不得[后]生感忆座人制诗嘲谢贺复继四首 四","author":"李贺","dynasty":"唐","verses":["寻常轻宋玉，今日嫁文鸯。","戟干横龙簴，刀环倚桂窗。","邀人裁半袖，端坐据胡床。","泪湿红轮重，栖乌上井梁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-1595f955-a610-478e-80f7-2d23500b9a6a","tags":[]},{"id":"poem-fd935c1cf235727e1733c3ac","title":"景灵旧钟","author":"李知退","dynasty":"宋","verses":["思昔祥符日，先皇建景灵。","六飞亲奠币，万国尽来庭。","睹物知全盛，闻声识典刑。","孤臣肠九折，不忍视斯铭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-af5d663c-ec12-4cfd-83d2-993f79b993db","tags":[]},{"id":"poem-fd9825172577efa27cb339ec","title":"减字木兰花·荷花风细","author":"谢逸","dynasty":"宋","verses":["荷花风细。","乞巧楼中凉似水。","天幕低垂。","新月弯环浅晕眉。","桥横乌鹊。","不负年年云外约。","残漏疏钟。","肠断朝霞一缕红。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-622","tags":[]},{"id":"poem-fda66d8f28044bb466365deb","title":"望梅花·数枝开与短墙平","author":"孙光宪","dynasty":"五代","verses":["数枝开与短墙平，见雪萼红跗相映，引起谁人边塞情。","帘外欲三更，吹断离愁月正明，空听隔江声。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-45","tags":[]},{"id":"poem-fdb452bd310ff5044ac11785","title":"又景亮惠藜杖赋绝句以谢  其一","author":"刘跂","dynasty":"宋","verses":["藜根矫矫似枯松，扶我蹒跚病力穷。","置几赐餐非所重，康宁愿学乐全翁。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1c163d8d-5e75-4410-9167-68e8b6402f3a","tags":[]},{"id":"poem-fdb985cba09d6c8e09eacb6e","title":"彤弓","author":"佚名","dynasty":"先秦","verses":["彤弓弨兮，受言藏之。我有嘉宾，中心贶之。钟鼓既设，一朝飨之。","彤弓弨兮，受言载之。我有嘉宾，中心喜之。钟鼓既设，一朝右之。","彤弓弨兮，受言櫜之。我有嘉宾，中心好之。钟鼓既设，一朝酬之。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-174","tags":[]},{"id":"poem-fdb9ab4b9031fdfc5e89f2c2","title":"小游仙诗九十八首 八","author":"曹唐","dynasty":"唐","verses":["风满涂山玉蕊稀，赤龙闲卧鹤东飞。","紫棃烂尽无人吃，何事韩君去不归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-c25f6713-1db4-410c-9567-47f7d6a74c5f","tags":[]},{"id":"poem-fdb9c91eca67f684c715ad9c","title":"九思·守志","author":"王逸","dynasty":"汉","verses":["陟玉峦兮逍遥，览高冈兮峣峣。","桂树列兮纷敷，吐紫华兮布条。","实孔鸾兮所居，今其集兮惟鸮。","乌鹊惊兮哑哑，余顾盼兮怊怊。","彼日月兮暗昧，障覆天兮祲氛。","伊我后兮不聪，焉陈诚兮效忠。","摅羽翮兮超俗，游陶遨兮养神。","乘六蛟兮蜿蝉，遂驰骋兮升云。","扬彗光兮为旗，秉电策兮为鞭。","朝晨发兮鄢郢，食时至兮增泉。","绕曲阿兮北次，造我车兮南端。","谒玄黄兮纳贽，崇忠贞兮弥坚。","历九宫兮遍观，睹秘藏兮宝珍。","就传说兮骑龙，与织女兮合婚。","举天罼兮掩邪，彀天弧兮射奸。","随真人兮翱翔，食元气兮长存。","望太微兮穆穆，睨三阶兮炳分。","相辅政兮成化，建烈业兮垂勋。","目瞥瞥兮西没，道遐回兮阻叹。","志稸积兮未通，怅敞罔兮自怜。","乱曰：天庭明兮云霓藏，三光朗兮镜万方。","斥蜥蜴兮进龟龙，策谋从兮翼机衡。","配稷契兮恢唐功，嗟英俊兮未为双。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-64","tags":[]},{"id":"poem-fdbf178a2a8c91928272121c","title":"次韵解枢干二首  其一","author":"陈造","dynasty":"宋","verses":["我方首儒冠，颇亦易此人。","尚友卑自汉，读书考先秦。","士或暗郑朴，识面蕲卜邻。","计疎志空勤，敝帚浪自珍。","口前齐东语，瞢欲润帝纶。","学如村社酝，百醨间一醇。","老蘗媚衰红，饱阅姚魏春。","顾惭误题品，五字极清新。","君才允文武，行矣拱帝宸。","余年念桑榆，归去侪编民。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-95ca2d6a-9660-485e-938d-37fe912ddcaf","tags":[]},{"id":"poem-fdd595824c8cbc0037ba9a0b","title":"宿冽上人房","author":"徐凝","dynasty":"唐","verses":["浮生不定若蓬飘，林下真僧偶见招。","觉后始知身是梦，更闻寒雨滴芭蕉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-4d73b24b-e146-42ff-b054-a36690c29a0c","tags":[]},{"id":"poem-fdd66a7bf1e49f154bc63077","title":"偈十六首  其一三","author":"释士珪","dynasty":"宋","verses":["老禅不打鼓山鼓，送老来看雁范山。","杰阁重楼都不见，溪边茅屋两三间。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c81028fd-6748-4bde-8c3e-a825be97a61e","tags":[]},{"id":"poem-fde02b9b1fd57cdfb8d2accb","title":"次日","author":"皎然","dynasty":"唐","verses":["野外有一人，独立无四隣。","彼见是我身，我见是彼身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6fb5985f-b3a7-4815-ae19-f7ab098c1e5c","tags":[]},{"id":"poem-fde727718e6f05ed2ee7d5ef","title":"木兰花・玉楼春·虫娘举措皆温润","author":"柳永","dynasty":"宋","verses":["虫娘举措皆温润。","每到婆娑偏恃俊。","香檀敲缓玉纤迟，画鼓声催莲步紧。","贪为顾盼夸风韵。","往往曲终情未尽。","坐中年少暗消魂，争问青鸾家远近。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-160","tags":[]},{"id":"poem-fdee726bf30886f99fd9e6c2","title":"溪行逢雨与柳中庸","author":"李端","dynasty":"唐","verses":["日落众山昏，萧萧暮雨繁。","那堪两处宿，共听一声猨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2d822a7d-7393-42c5-9366-263c627b8403","tags":[]},{"id":"poem-fdf51b782503388934f08e05","title":"春怨","author":"杨凝","dynasty":"唐","verses":["花满帘栊欲度春，此时夫壻在咸秦。","绿窗孤寝难成寐，紫燕双飞似弄人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-655946f1-eda9-469c-bc5b-da8dc465e9cf","tags":[]},{"id":"poem-fe02d03a72a23801ef1bc397","title":"秋日同觉公上人眺慈恩塔六韵","author":"李洞","dynasty":"唐","verses":["九级耸莲宫，晴登袖拂虹。","房廊窥井底，世界出笼中。","照牖三山火，吹铃八极风。","细闻槎客语，遥辨海鱼冲。","禁静声连北，江寒影在东。","谒师开秘锁，尘日闭虚空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-216c4a17-acf7-4d0e-ab84-84390a7a84fc","tags":[]},{"id":"poem-fe1bfba02dc1952e75eaf808","title":"眉妩·渐新痕悬柳","author":"王沂孙","dynasty":"宋","verses":["渐新痕悬柳，澹彩穿花，依约破初暝。","便有团圆意，深深拜，相逢谁在香径。","画眉未稳，料素娥、犹带离恨。","最堪爱、一曲银钩小，宝帘挂秋冷。","千古盈亏休问。","叹慢磨玉斧，难补金镜。","太液池犹在，凄凉处、何人重赋清景。","故山夜永。","试待他、窥户端正。","看云外山河，还老尽、桂花影。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-249","tags":["宋词三百首"]},{"id":"poem-fe1cb6b0058c2ccc3a2e2bca","title":"女冠子·淡花瘦玉","author":"孙光宪","dynasty":"五代","verses":["淡花瘦玉，依约神仙妆束。","佩琼文，瑞露通宵贮，幽香尽日焚。","碧纱笼绛节，黄藕冠浓云。","勿以吹箫伴，不同群。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-24","tags":[]},{"id":"poem-fe2290d0c3046b25efc535ef","title":"郊庙歌辞 祀九宫贵神乐章 肃和","author":"不详","dynasty":"唐","verses":["精意严恭，明祠丰洁。","献酬既备，俎豆斯撤。","日丽天仪，风和乐节。","事光祀典，福覃有截。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-80910f66-39da-4bc3-a42e-fabe2efd9c63","tags":[]},{"id":"poem-fe2370a44d798ae67c06b0b4","title":"玩花五首 五","author":"徐凝","dynasty":"唐","verses":["花到蔷薇明艳绝，燕支颗破麦风秋。","一番弄色一番退，小妇轻妆大妇愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-566a30d5-2bb2-4cc4-95c0-babac12c7f99","tags":[]},{"id":"poem-fe262703c0363c813ad561d7","title":"郊庙歌辞 夕月乐章 肃和","author":"不详","dynasty":"唐","verses":["测妙为神，通微曰圣。","坎祀贻则，郊禋展敬。","璧荐登光，金歌动映。","以载嘉德，以流曾庆。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-289d4243-4767-4538-acff-d018f3e7dd95","tags":[]},{"id":"poem-fe27363ecb8998bd6edd503e","title":"颂古七十六首  其一○","author":"释士珪","dynasty":"宋","verses":["少室山前风过耳，九年人事随流水。","若还是弄潮人，切须莫入洪波里。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-edf67f98-7394-4f69-94b7-d2f6a3647041","tags":[]},{"id":"poem-fe28de92ddcf6842c3c9da85","title":"兵要望江南 《周易》占候第二十六（三十七首） 三十一","author":"易静","dynasty":"唐","verses":["归魂卦，三四动爻凶。","若制鬼爻凶转遂（辛本、川本作「队」），若逢天喜好回军，不久却抽兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-476c9956-3aed-4176-bf85-25f295a5a850","tags":[]},{"id":"poem-fe34be503449e43becc7c47a","title":"李粹伯对月见怀次韵","author":"曾协","dynasty":"宋","verses":["初收雨脚万丝悬，妙手谁人补漏天。","佳月素华迷夜旦，好诗余味满中边。","裴徊无奈谢希逸，齁䶎总输边孝先。","见说百篇酬一斗，高门重见酒中仙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-cbbd25ff-53fb-4493-9b67-98b9a2160e55","tags":[]},{"id":"poem-fe436dd80c1e1fe1b748f7d6","title":"秋日奉陪王丰甫许子大康平仲游贤沙宿凤池登升山偶成二首  其一","author":"李纲","dynasty":"宋","verses":["飞来耸翠一峰孤，凤沼幽深若画图。","钓艇谢亡难复契，弹琴颖在且相娱。","心闲自与亲泉石，车穏何妨载酒壶。","万壑千岩争竞处，不须惆怅忆东吴。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-dadf40a6-0030-45eb-ac6c-5c91234ca369","tags":[]},{"id":"poem-fe48a3252a57e8673e369a50","title":"苦寒行","author":"曹操","dynasty":"汉","verses":["北上太行山，艰哉何巍巍！","羊肠坂诘屈，车轮为之摧。","树木何萧瑟！北风声正悲。","熊罴对我蹲，虎豹夹路啼。","溪谷少人民，雪落何霏霏！","延颈长叹息，远行多所怀。","我心何怫郁？思欲一东归。","水深桥梁绝，中路正徘徊。","迷惑失故路，薄暮无宿栖。","行行日已远，人马同时饥。","担囊行取薪，斧冰持作糜。","悲彼东山诗，悠悠使我哀。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-8","tags":[]},{"id":"poem-fe52b39b21513553a0e609cc","title":"念奴娇·吴松江畔","author":"崔敦礼","dynasty":"宋","verses":["吴松江畔，对烟波浩渺，相忘鸥鸟。","日日篮舆湖上路，十里珠帘惊笑。","高下楼台，浅深溪坞，著此香山老。","辋川图上，好风吹梦曾到。","不用金谷繁华，碧城修竹，自比封君号。","万壑千岩天付与，一洗寒酸郊岛。","霖雨方思，烟尘未扫，合挽三江倒。","功成名遂，却来依旧华表。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-407","tags":[]},{"id":"poem-fe53cee0cacfa2237bbfe238","title":"读《汉书》作","author":"刘知几","dynasty":"唐","verses":["汉王有天下，欻起布衣中。","奋飞出草泽，啸咤驭群雄。","淮阴既附鳯，黥彭亦攀龙，一朝逢运会，南面皆王公。","鱼得自忘筌，鸟尽必藏弓，咄嗟罹鼎俎，赤族无遗踪。","智裁（哉）张子房，处世独为工；功成薄爱（受）[一]赏，（「爱」，蒋云当作「爵」。","）高举追赤松。","知止信无辱，身安道亦隆，悠悠[千]载后，击抃（柝）[二]仰遗风。","（「击抃」，蒋、项皆云「抃」字不误。","）（[一][二]并依俞说。","刘云：「左思《咏史》，功成不受爵。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-63e84be7-734e-41a9-b173-4a79de070797","tags":[]},{"id":"poem-fe62f9eec0dce6dc3ff3ed6c","title":"清平乐·留春不住","author":"王安国","dynasty":"宋","verses":["留春不住。","费尽莺儿语。","满地残红宫锦污。","昨夜南园风雨。","小怜初上琵琶。","晓来思绕天涯。","不肯画堂朱户，春风自在梨花。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-18","tags":["宋词三百首"]},{"id":"poem-fe70ff9bad672b4450957e39","title":"杨柳枝寿杯词十八首 八","author":"司空图","dynasty":"唐","verses":["稻畦分影向江邨，憔悴经霜只半存。","昨日流莺今不见，乱萤飞出照黄昏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-df98b09e-516c-44f6-893b-91f28ed1b5ae","tags":[]},{"id":"poem-fe741b09d632d8eba85978c7","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["你闲时叫小二便走。","(末白)如何？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2509","tags":[]},{"id":"poem-fe76c30a5ca0d50d92fae079","title":"别双温树","author":"李绅","dynasty":"唐","verses":["翠条盈尺怜孤秀，植向西窗待月轩。","轻剪绿丝秋叶暗，密扶纤干夏阴繁。","故山手种空怀想，温室心知不敢言。","看尔拂云今得地，莫随陵谷改深根。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-e3d09c65-b21d-4b38-bb61-7a5a13a75bab","tags":[]},{"id":"poem-fe7aa0ec703e0a7f20d0056b","title":"好姐姐","author":"徐田臣《杀狗记》","dynasty":"元","verses":["告禀龙图大尹，状告那孙华孙荣。","昨夜三更，悄然来叩门，道杀人命，要教我两人偷埋殡。","望乞恩官详事因。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1944","tags":[]},{"id":"poem-fe831c67cb8fbf804c530122","title":"菩萨蛮·哀筝一弄湘江曲","author":"晏几道","dynasty":"宋","verses":["哀筝一弄湘江曲。","声声写尽湘波绿。","纤指十三弦。","细将幽恨传。","当筵秋水慢。","玉柱斜飞雁。","弹到断肠时。","春山眉黛低。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-27","tags":["宋词三百首"]},{"id":"poem-fe83d73736447c19848701bb","title":"中津","author":"释居简","dynasty":"宋","verses":["帆挂中津趁落潮，且停双桨不须摇。","却将中散凭阑意，直送孤鸿到玉霄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-b96f1b48-3186-42c5-8eb6-5284549abafb","tags":[]},{"id":"poem-fe8784eb1893c55e2c6091b2","title":"题谢处士山斋","author":"宋之问","dynasty":"唐","verses":["那有唐年客，青山独闭门。","云泉一少事，琴史皆忘喧。","在濬人犹絷，迁乔友未言。","不知幽谷草，何意老王孙？","（此诗见《永乐大典》卷二五三九「七皆」「斋」字「山斋」条。","〖三函三十册〗）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6f0b5f47-9d4a-459c-8b03-ba673e8abe2d","tags":[]},{"id":"poem-fe88e9c767e9a727b4fa9e9c","title":"点绛唇·罗幕重重","author":"张纲","dynasty":"宋","verses":["罗幕重重，画堂迎腊和风转。","玳筵高展。","知是群仙宴。","银鸭香浮，红袖翻歌扇。","金杯劝。","深深祝愿。","争把蟠桃献。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-655","tags":[]},{"id":"poem-fe88e9f31e09ed87445decc8","title":"解连环·怨怀无托","author":"周邦彦","dynasty":"宋","verses":["怨怀无托。","嗟情人断绝，信音辽邈。","信妙手、能解连环，似风散雨收，雾轻云薄。","燕子楼空，暗尘锁、一床弦索。","想移根换叶。","尽是旧时，手种红药。","汀洲渐生杜若。","料舟依岸曲，人在天角。","谩记得、当日音书，把闲语闲言，待总烧却。","水驿春回，望寄我、江南梅萼。","拚今生，对花对酒，为伊落泪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-227","tags":["宋词三百首"]},{"id":"poem-fe8d07d8ae1b73f250d4c143","title":"横吹曲辞 入塞曲 二","author":"僧贯休","dynasty":"唐","verses":["方见将军贵，分明对冕旒。","圣恩如远被，狂虏不难收。","臣节唯期死，功勋敢望侯。","终辞修里第，从此出皇州。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f5c68f7a-8b75-42f3-b211-39bad532530b","tags":[]},{"id":"poem-fe97268874cc6a324b1245bf","title":"琴曲歌辞 列女操","author":"孟郊","dynasty":"唐","verses":["梧桐相待老，鸳鸯会双死。","贞妇贵徇夫，舍生亦如此。","波澜誓不起，妾心井中水。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7ccd9915-51a1-4748-9989-af243036455b","tags":["唐诗三百首","赞颂","妇女","乐府"]},{"id":"poem-fea8293004c7e964521cb2ea","title":"旱麓","author":"佚名","dynasty":"先秦","verses":["瞻彼旱麓，榛楛济济。岂弟君子，干禄岂弟。","瑟彼玉瓒，黄流在中。岂弟君子，福禄攸降。","鸢飞戾天，鱼跃于渊。岂弟君子，遐不作人？","清酒既载，骍牡既备。以享以祀，以介景福。","瑟彼柞棫，民所燎矣。岂弟君子，神所劳矣。","莫莫葛藟，施于条枚。岂弟君子，求福不回。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-238","tags":[]},{"id":"poem-feaa6bae50f63fc0077f93ed","title":"早发故园","author":"马戴","dynasty":"唐","verses":["语别在中夜，登车离故乡。","曙钟寒出岳，残月迥凝霜。","风柳条多折，沙云气尽黄。","行逢海西鴈，零落不成行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-e3bb8811-902f-45ed-bbde-517f8c5a1604","tags":[]},{"id":"poem-feb1aa9db7008972f4ce361a","title":"再和","author":"张栻","dynasty":"宋","verses":["想得经行与客俱，身强宁复要人扶。","晚来山色应难尽，十里青苍看有无。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-fb516a9d-25ed-4674-b78c-069493701640","tags":[]},{"id":"poem-feb4e9b031a921deced696a3","title":"九歌·河伯","author":"屈原","dynasty":"先秦","verses":["与女游兮九河，冲风起兮水扬波。","乘水车兮荷盖，驾两龙兮骖螭。","登昆仑兮四望，心飞扬兮浩荡。","日将暮兮怅忘归，惟极浦兮寤怀。","鱼鳞屋兮龙堂，紫贝阙兮珠宫。","灵何惟兮水中。","乘白鼋兮逐文鱼，与女游兮河之渚。","流澌纷兮将来下。","子交手兮东行，送美人兮南浦。","波滔滔兮来迎，鱼鳞鳞兮媵予。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-8","tags":[]},{"id":"poem-feb68eef09294c4f1f09062b","title":"浪淘沙·铅汞要加添","author":"宋先生","dynasty":"宋","verses":["铅汞要加添。","火候频煎。","体中气足返阳全。","养就婴儿并姹女，同坐同眠。","髓实自身坚。","运满三田。","刀圭服了得神仙。","只候功成并行满，独步朝元。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-295","tags":[]},{"id":"poem-feba482fde8c7b7db5bd6f87","title":"阮郎归·儿童嬉戏杏花堤","author":"晁补之","dynasty":"宋","verses":["儿童嬉戏杏花堤。","春归不解悲。","重来草露湿人衣。","无花空绕枝。","曾学道，久望机。","一尊甘若饴。","平生鱼鸟与同归。","临风心自知。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-198","tags":[]},{"id":"poem-fec51c139d541fbc81aff867","title":"卓笔峰","author":"王十朋","dynasty":"宋","verses":["束缚真凭造化功，巍巍直气贯鸿蒙。","雨将苔色生彤管，山吐虹光遶兔锋。","未数如椽曾入梦，误疑怪事尚书空。","士人毛颖多荣辱，恩宠才衰便不同。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-3aabd5ee-b583-487d-8f72-afbae03150dd","tags":[]},{"id":"poem-fed30af5894651615a647dd9","title":"传言玉女","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["烛影摇红，帘幕瑞烟浮动，画堂中珠围翠拥。","妆台对月，下鸾鹤神仙仪从。","玉箫声里，一双鸣凤。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5057","tags":[]},{"id":"poem-fed543d76584c10bdb34a2fb","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["妾的衷肠事，万万千，说来又怕添萦绊。","六十日夫妻恩情断，八十岁父母如何展？教我如何不怨？(合前)(末唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4950","tags":[]},{"id":"poem-fedc4df11da10aa77e3944ba","title":"天仙子·月落城乌啼未了","author":"纳兰性德","dynasty":"清","verses":["月落城乌啼未了，起来翻为无眠早。","薄霜庭院怯生衣，心悄悄，红阑绕。","此情待共谁人晓。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-110","tags":[]}];
